DECLARE
    v_row public.tip_pools;
BEGIN
    IF NOT (
        public.is_manager_or_admin()
        OR EXISTS (
            SELECT 1
            FROM public.tip_pool_editors e
            WHERE e.user_id = auth.uid()
        )
    ) THEN
        RAISE EXCEPTION 'PERMISSION_DENIED: only manager/admin or tip_pool_editors can upsert tip pools';
    END IF;

    IF p_pool_type NOT IN ('weekday', 'weekend') THEN
        RAISE EXCEPTION 'VALIDATION_ERROR: pool_type must be weekday|weekend';
    END IF;

    IF COALESCE(p_cash_total, 0) < 0 THEN
        RAISE EXCEPTION 'VALIDATION_ERROR: cash_total must be >= 0';
    END IF;

    INSERT INTO public.tip_pools (pool_type, cash_total, cash_breakdown, notes, created_by)
    VALUES (p_pool_type, COALESCE(p_cash_total, 0), COALESCE(p_cash_breakdown, '{}'::jsonb), p_notes, auth.uid())
    ON CONFLICT (pool_type)
    DO UPDATE SET
        cash_total = EXCLUDED.cash_total,
        cash_breakdown = EXCLUDED.cash_breakdown,
        notes = EXCLUDED.notes,
        updated_at = now()
    RETURNING * INTO v_row;

    RETURN v_row;
END;

DECLARE
    v_order_id      uuid;
    v_i             integer;
    v_rows_affected integer;
    v_abs_delta     integer;
BEGIN
    -- Buscar la orden ACTIVA actual para este numero_documento.
    -- Si existe, la usamos. Si no (mesa nueva o reapertura tras cierre), creamos una nueva.
    SELECT id INTO v_order_id
    FROM public.kds_orders
    WHERE origen_referencia = NEW.numero_documento
      AND estado = 'activa'
    LIMIT 1;

    IF v_order_id IS NULL THEN
        -- Nueva apertura: insertar una nueva orden independiente
        INSERT INTO public.kds_orders (origen_referencia, mesa, estado)
        VALUES (NEW.numero_documento, COALESCE(NEW.mesa, 'Mesa Desc.'), 'activa')
        RETURNING id INTO v_order_id;
    ELSE
        -- Orden activa existente: solo actualizar mesa si cambió
        UPDATE public.kds_orders
        SET mesa = COALESCE(NEW.mesa, mesa)
        WHERE id = v_order_id;
    END IF;

    IF NEW.cantidad_delta > 0 THEN
        -- Añadir líneas nuevas
        FOR v_i IN 1..NEW.cantidad_delta LOOP
            INSERT INTO public.kds_order_lines (kds_order_id, producto_nombre, notas)
            VALUES (v_order_id, NEW.producto_nombre, NEW.notas);
        END LOOP;

    ELSIF NEW.cantidad_delta < 0 THEN
        -- Cancelar líneas (empezar por pendientes, luego terminadas)
        v_abs_delta := abs(NEW.cantidad_delta);

        WITH lines_to_cancel AS (
            SELECT id FROM public.kds_order_lines
            WHERE kds_order_id    = v_order_id
              AND producto_nombre = NEW.producto_nombre
              AND COALESCE(notas, '') = COALESCE(NEW.notas, '')
              AND estado = 'pendiente'
            ORDER BY created_at DESC LIMIT v_abs_delta
        )
        UPDATE public.kds_order_lines
        SET estado = 'cancelado', completed_at = NOW()
        WHERE id IN (SELECT id FROM lines_to_cancel);

        GET DIAGNOSTICS v_rows_affected = ROW_COUNT;

        IF v_rows_affected < v_abs_delta THEN
            WITH finished_to_cancel AS (
                SELECT id FROM public.kds_order_lines
                WHERE kds_order_id    = v_order_id
                  AND producto_nombre = NEW.producto_nombre
                  AND COALESCE(notas, '') = COALESCE(NEW.notas, '')
                  AND estado = 'terminado'
                ORDER BY completed_at DESC LIMIT (v_abs_delta - v_rows_affected)
            )
            UPDATE public.kds_order_lines
            SET estado = 'cancelado', completed_at = NOW()
            WHERE id IN (SELECT id FROM finished_to_cancel);
        END IF;
    END IF;

    NEW.procesado_kds := true;
    RETURN NEW;
END;

DECLARE
  pu text := public.normalize_pricing_unit(p_purchase_unit);
  size_unit text := public.normalize_pricing_unit(coalesce(p_pack_unit_size_unit, 'ud'));
  size_qty numeric := COALESCE(p_pack_unit_size_qty, 1);
  units_in_pack numeric := COALESCE(p_pack_units, 0);
  converted_size numeric;
  denom numeric;
BEGIN
  IF p_pack_price IS NULL OR p_pack_price < 0 THEN
    RAISE EXCEPTION 'pack_price inválido (debe ser >= 0)';
  END IF;

  IF units_in_pack IS NULL OR units_in_pack <= 0 THEN
    RAISE EXCEPTION 'pack_units inválido (debe ser > 0)';
  END IF;

  IF size_qty IS NULL OR size_qty <= 0 THEN
    RAISE EXCEPTION 'pack_unit_size_qty inválido (debe ser > 0)';
  END IF;

  converted_size := public.convert_pricing_qty(size_qty, size_unit, pu);
  IF converted_size IS NULL OR converted_size <= 0 THEN
    RAISE EXCEPTION 'Conversión no soportada: % -> %', size_unit, pu;
  END IF;

  denom := units_in_pack * converted_size;
  IF denom <= 0 THEN
    RAISE EXCEPTION 'Denominador inválido al calcular current_price';
  END IF;

  RETURN (p_pack_price / denom);
END;

DECLARE
  mode text := coalesce(NEW.supplier_pricing_mode, 'per_purchase_unit');
  pu   text := public.normalize_pricing_unit(NEW.purchase_unit);
BEGIN
  NEW.supplier_pricing_mode := mode;
  NEW.purchase_unit          := pu;
  NEW.unit_type              := pu;
  -- Mantener base_unit y unit sincronizados con purchase_unit
  NEW.base_unit              := public.derive_base_unit(pu);
  NEW.unit                   := NEW.base_unit;

  IF mode = 'per_pack' THEN
    NEW.current_price := public.compute_ingredient_current_price_from_pack(
      NEW.pack_price,
      NEW.pack_units,
      NEW.pack_unit_size_qty,
      NEW.pack_unit_size_unit,
      NEW.purchase_unit
    );
  ELSE
    NEW.pack_price         := NULL;
    NEW.pack_units         := NULL;
    NEW.pack_unit_size_qty := NULL;
    NEW.pack_unit_size_unit := NULL;
  END IF;

  RETURN NEW;
END;

DECLARE
  v_id uuid;
BEGIN
  -- Solo cocina por RPC (TPV inserta con service role directamente)
  IF p_event_type IS NULL OR btrim(p_event_type) = '' THEN
    RAISE EXCEPTION 'event_type requerido';
  END IF;
  IF p_id_ticket IS NULL OR btrim(p_id_ticket) = '' THEN
    RAISE EXCEPTION 'id_ticket requerido';
  END IF;
  IF COALESCE(p_qty, 0) <= 0 THEN
    RAISE EXCEPTION 'qty debe ser > 0';
  END IF;
  INSERT INTO public.kds_events (
    source, source_event_id, id_ticket, mesa, event_type,
    articulo_id, producto_nombre, notas, qty
  )
  VALUES (
    'kitchen',
    NULLIF(btrim(p_source_event_id), ''),
    btrim(p_id_ticket),
    NULLIF(btrim(p_mesa), ''),
    btrim(p_event_type),
    p_articulo_id,
    NULLIF(btrim(p_producto_nombre), ''),
    p_notas,
    p_qty
  )
  ON CONFLICT (source, source_event_id) DO NOTHING
  RETURNING id INTO v_id;
  IF v_id IS NULL AND p_source_event_id IS NOT NULL AND btrim(p_source_event_id) <> '' THEN
    SELECT id INTO v_id
    FROM public.kds_events
    WHERE source = 'kitchen' AND source_event_id = btrim(p_source_event_id)
    LIMIT 1;
  END IF;
  RETURN v_id;
END;

DECLARE
  vrec jsonb;
  v_target_qty int;
  v_articulo_id int;
  v_nombre text;
  v_notas text;
  v_notas_n text;
  v_envia_art boolean;
  v_envia_dept boolean;
  v_effective_envia boolean;
  v_departamento_id integer;
  r record;
  v_existing_effective int;
  v_delta int;
  v_source_event_id text;
  v_ts text;
BEGIN
  IF p_id_ticket IS NULL OR btrim(p_id_ticket) = '' THEN
    RETURN;
  END IF;
  IF p_productos IS NULL THEN
    p_productos := '[]'::jsonb;
  END IF;
  v_ts := NULLIF(btrim(COALESCE(p_timestamp_tpv, '')), '');
  DROP TABLE IF EXISTS tmp_kds_v2_targets;
  CREATE TEMP TABLE tmp_kds_v2_targets (
    articulo_id int NOT NULL,
    notas_n text NOT NULL,
    qty int NOT NULL,
    producto_nombre text,
    PRIMARY KEY (articulo_id, notas_n)
  ) ON COMMIT DROP;
  -- 1) Construir mapa objetivo desde snapshot TPV (solo artículos que envían a KDS)
  FOR vrec IN SELECT * FROM jsonb_array_elements(p_productos)
  LOOP
    v_target_qty := COALESCE(NULLIF(floor(COALESCE((vrec->>'unidades')::numeric, 0))::int, 0), 0);
    IF v_target_qty <= 0 THEN
      CONTINUE;
    END IF;
    v_nombre := NULLIF(btrim(COALESCE(vrec->>'nombre', '')), '');
    v_notas := COALESCE(vrec->>'notas', '');
    v_notas_n := COALESCE(v_notas, '');
    v_articulo_id := NULLIF((vrec->>'articulo_id')::int, 0);
    IF v_articulo_id IS NULL AND v_nombre IS NOT NULL THEN
      SELECT a.id
      INTO v_articulo_id
      FROM public.bdp_articulos a
      WHERE lower(btrim(a.nombre)) = lower(btrim(v_nombre))
      LIMIT 1;
    END IF;
    v_effective_envia := FALSE;
    IF v_articulo_id IS NOT NULL THEN
      SELECT a.envia_a_kds, a.departamento_id
      INTO v_envia_art, v_departamento_id
      FROM public.bdp_articulos a
      WHERE a.id = v_articulo_id
      LIMIT 1;
      IF v_envia_art IS TRUE THEN
        v_effective_envia := TRUE;
      ELSIF v_envia_art IS FALSE THEN
        v_effective_envia := FALSE;
      ELSE
        SELECT d.envia_a_kds
        INTO v_envia_dept
        FROM public.bdp_departamentos d
        WHERE d.id = v_departamento_id
        LIMIT 1;
        v_effective_envia := COALESCE(v_envia_dept, FALSE);
      END IF;
    END IF;
    IF v_effective_envia IS NOT TRUE THEN
      CONTINUE;
    END IF;
    INSERT INTO tmp_kds_v2_targets (articulo_id, notas_n, qty, producto_nombre)
    VALUES (v_articulo_id, v_notas_n, v_target_qty, v_nombre)
    ON CONFLICT (articulo_id, notas_n) DO UPDATE
      SET qty = tmp_kds_v2_targets.qty + EXCLUDED.qty,
          producto_nombre = COALESCE(EXCLUDED.producto_nombre, tmp_kds_v2_targets.producto_nombre);
  END LOOP;
  -- 2) Unir objetivo ∪ existente (proyección), calculando delta sobre "effective_added"
  FOR r IN
    SELECT
      COALESCE(t.articulo_id, e.articulo_id) AS articulo_id,
      COALESCE(t.notas_n, e.notas_norm) AS notas_n,
      COALESCE(t.qty, 0) AS target_qty,
      COALESCE(t.producto_nombre, e.producto_nombre) AS producto_nombre,
      COALESCE(e.qty_added, 0) AS qty_added,
      COALESCE(e.qty_cancel_notice, 0) AS qty_cancel_notice
    FROM tmp_kds_v2_targets t
    FULL OUTER JOIN (
      SELECT
        l.articulo_id,
        l.notas_norm,
        l.producto_nombre,
        l.qty_added,
        l.qty_cancel_notice
      FROM public.kds_projection_lines l
      WHERE l.id_ticket = btrim(p_id_ticket)
    ) e
      ON COALESCE(t.articulo_id, -2147483648) = COALESCE(e.articulo_id, -2147483648)
     AND COALESCE(t.notas_n, '') = COALESCE(e.notas_norm, '')
    WHERE COALESCE(t.articulo_id, e.articulo_id) IS NOT NULL
  LOOP
    v_existing_effective := GREATEST(0, (r.qty_added - r.qty_cancel_notice));
    v_delta := COALESCE(r.target_qty, 0) - v_existing_effective;
    IF v_delta = 0 THEN
      CONTINUE;
    END IF;
    IF v_ts IS NOT NULL THEN
      v_source_event_id := concat_ws('|', 'tpv', btrim(p_id_ticket), v_ts, r.articulo_id::text, COALESCE(r.notas_n, ''), CASE WHEN v_delta > 0 THEN 'item_added' ELSE 'item_cancel_notice' END, abs(v_delta)::text);
    ELSE
      v_source_event_id := NULL;
    END IF;
    IF v_delta > 0 THEN
      INSERT INTO public.kds_events (
        source, source_event_id, id_ticket, mesa, event_type,
        articulo_id, producto_nombre, notas, qty,
        payload
      )
      VALUES (
        'tpv',
        v_source_event_id,
        btrim(p_id_ticket),
        NULLIF(btrim(p_mesa), ''),
        'item_added',
        r.articulo_id,
        NULLIF(btrim(COALESCE(r.producto_nombre, '')), ''),
        NULLIF(COALESCE(r.notas_n, ''), ''),
        v_delta,
        jsonb_build_object(
          'notas_comanda', NULLIF(btrim(COALESCE(p_notas_comanda, '')), ''),
          'numero_documento', NULLIF(btrim(COALESCE(p_numero_documento, '')), ''),
          'nombre_cliente', NULLIF(btrim(COALESCE(p_nombre_cliente, '')), '')
        )
      )
      ON CONFLICT (source, source_event_id) DO NOTHING;
    ELSE
      INSERT INTO public.kds_events (
        source, source_event_id, id_ticket, mesa, event_type,
        articulo_id, producto_nombre, notas, qty,
        payload
      )
      VALUES (
        'tpv',
        v_source_event_id,
        btrim(p_id_ticket),
        NULLIF(btrim(p_mesa), ''),
        'item_cancel_notice',
        r.articulo_id,
        NULLIF(btrim(COALESCE(r.producto_nombre, '')), ''),
        NULLIF(COALESCE(r.notas_n, ''), ''),
        abs(v_delta),
        jsonb_build_object(
          'notas_comanda', NULLIF(btrim(COALESCE(p_notas_comanda, '')), ''),
          'numero_documento', NULLIF(btrim(COALESCE(p_numero_documento, '')), ''),
          'nombre_cliente', NULLIF(btrim(COALESCE(p_nombre_cliente, '')), '')
        )
      )
      ON CONFLICT (source, source_event_id) DO NOTHING;
    END IF;
  END LOOP;
END;

DECLARE
  cmd record;
BEGIN
  FOR cmd IN
    SELECT *
    FROM pg_event_trigger_ddl_commands()
    WHERE command_tag IN ('CREATE TABLE', 'CREATE TABLE AS', 'SELECT INTO')
      AND object_type IN ('table','partitioned table')
  LOOP
     IF cmd.schema_name IS NOT NULL AND cmd.schema_name IN ('public') AND cmd.schema_name NOT IN ('pg_catalog','information_schema') AND cmd.schema_name NOT LIKE 'pg_toast%' AND cmd.schema_name NOT LIKE 'pg_temp%' THEN
      BEGIN
        EXECUTE format('alter table if exists %s enable row level security', cmd.object_identity);
        RAISE LOG 'rls_auto_enable: enabled RLS on %', cmd.object_identity;
      EXCEPTION
        WHEN OTHERS THEN
          RAISE LOG 'rls_auto_enable: failed to enable RLS on %', cmd.object_identity;
      END;
     ELSE
        RAISE LOG 'rls_auto_enable: skip % (either system schema or not in enforced list: %.)', cmd.object_identity, cmd.schema_name;
     END IF;
  END LOOP;
END;

DECLARE
  resultado json;
BEGIN
  SELECT json_build_object(
    'total_tickets', count(*),
    'facturacion', coalesce(sum(total_documento), 0)
  ) INTO resultado
  FROM public.tickets_marbella
  WHERE fecha = fecha_objetivo;
  
  RETURN resultado;
END;

DECLARE
    k text;
    v integer;
BEGIN
    -- Si no hay desglose de billetes, no tocamos el inventario físico
    IF NEW.breakdown IS NULL OR NEW.breakdown = '{}'::jsonb THEN
        RETURN NEW;
    END IF;

    IF NEW.type = 'ADJUSTMENT' THEN
        -- Arqueo: Sobrescribir la realidad física por completo
        UPDATE public.cash_box_inventory SET quantity = 0 WHERE box_id = NEW.box_id;
        
        FOR k, v IN SELECT * FROM jsonb_each_text(NEW.breakdown) LOOP
            INSERT INTO public.cash_box_inventory (box_id, denomination, quantity)
            VALUES (NEW.box_id, k::numeric, v::integer)
            ON CONFLICT (box_id, denomination) DO UPDATE SET quantity = EXCLUDED.quantity;
        END LOOP;

    ELSIF NEW.type IN ('IN', 'CLOSE_ENTRY') THEN
        -- Entrada: Sumar billetes
        FOR k, v IN SELECT * FROM jsonb_each_text(NEW.breakdown) LOOP
            UPDATE public.cash_box_inventory
            SET quantity = quantity + v::integer
            WHERE box_id = NEW.box_id AND denomination = k::numeric;
        END LOOP;

    ELSIF NEW.type = 'OUT' THEN
        -- Salida: Restar billetes
        FOR k, v IN SELECT * FROM jsonb_each_text(NEW.breakdown) LOOP
            UPDATE public.cash_box_inventory
            SET quantity = quantity - v::integer
            WHERE box_id = NEW.box_id AND denomination = k::numeric;
        END LOOP;
    END IF;

    -- Actualizar el caché de dinero total físico de la tabla cash_boxes
    UPDATE public.cash_boxes
    SET current_balance = (
        SELECT COALESCE(SUM(denomination * quantity), 0)
        FROM public.cash_box_inventory
        WHERE box_id = NEW.box_id
    )
    WHERE id = NEW.box_id;

    RETURN NEW;
END;

DECLARE
    v_integer_part numeric;
    v_decimal_part numeric;
    v_minutes numeric;
    v_fraction numeric;
BEGIN
    IF p_hours IS NULL THEN RETURN 0; END IF;
    
    -- Math.floor equivalente en PostgreSQL
    v_integer_part := floor(p_hours);
    v_decimal_part := p_hours - v_integer_part;
    v_minutes := v_decimal_part * 60;
    
    IF v_minutes <= 20 THEN
        v_fraction := 0.0;
    ELSIF v_minutes <= 50 THEN
        v_fraction := 0.5;
    ELSE
        v_fraction := 1.0;
    END IF;
    
    RETURN v_integer_part + v_fraction;
END;

DECLARE
    v_first_log_date date;
    v_user_id uuid;
BEGIN
    -- Obtener la fecha del primer fichaje histórico
    SELECT MIN(clock_in::date) INTO v_first_log_date FROM public.time_logs;
    IF v_first_log_date IS NULL THEN
        RETURN '{"success": true, "message": "No hay fichajes que procesar."}'::jsonb;
    END IF;

    -- Iterar sobre cada usuario con fichajes y delegar en fn_recalc
    FOR v_user_id IN 
        SELECT DISTINCT user_id FROM public.time_logs
    LOOP
        PERFORM public.fn_recalc_and_propagate_snapshots(v_user_id, v_first_log_date);
    END LOOP;

    RETURN '{"success": true, "message": "Recálculo global completado con éxito vía fn_recalc_and_propagate_snapshots."}'::jsonb;
END;

DECLARE
    key_val text;
    qty numeric;
    denom numeric;
BEGIN
    -- Handle DELETE or UPDATE (revert old impact)
    IF TG_OP = 'DELETE' OR TG_OP = 'UPDATE' THEN
        -- If it was IN or CLOSE_ENTRY, subtract the old breakdown
        IF OLD.type IN ('IN', 'CLOSE_ENTRY') AND OLD.breakdown IS NOT NULL THEN
            FOR key_val, qty IN SELECT * FROM jsonb_each_text(OLD.breakdown)
            LOOP
                denom := key_val::numeric;
                qty := qty::numeric;
                UPDATE public.cash_box_inventory 
                SET quantity = quantity - qty
                WHERE box_id = OLD.box_id AND denomination = denom;
            END LOOP;
        
        -- If it was OUT, add back the old breakdown
        ELSIF OLD.type = 'OUT' AND OLD.breakdown IS NOT NULL THEN
            FOR key_val, qty IN SELECT * FROM jsonb_each_text(OLD.breakdown)
            LOOP
                denom := key_val::numeric;
                qty := qty::numeric;
                UPDATE public.cash_box_inventory 
                SET quantity = quantity + qty
                WHERE box_id = OLD.box_id AND denomination = denom;
            END LOOP;
            
        -- If it was SWAP, revert the in/out
        ELSIF OLD.type = 'SWAP' AND OLD.breakdown IS NOT NULL THEN
            -- Revert 'in' (subtract what came in)
            IF OLD.breakdown ? 'in' THEN
                FOR key_val, qty IN SELECT * FROM jsonb_each_text(OLD.breakdown->'in')
                LOOP
                    denom := key_val::numeric;
                    qty := qty::numeric;
                    UPDATE public.cash_box_inventory 
                    SET quantity = quantity - qty
                    WHERE box_id = OLD.box_id AND denomination = denom;
                END LOOP;
            END IF;
            -- Revert 'out' (add back what went out)
            IF OLD.breakdown ? 'out' THEN
                FOR key_val, qty IN SELECT * FROM jsonb_each_text(OLD.breakdown->'out')
                LOOP
                    denom := key_val::numeric;
                    qty := qty::numeric;
                    UPDATE public.cash_box_inventory 
                    SET quantity = quantity + qty
                    WHERE box_id = OLD.box_id AND denomination = denom;
                END LOOP;
            END IF;
            
        -- Arqueos (ADJUSTMENT) overwrites, so reverting a delete is complicated. Usually we don't delete arqueos.
        END IF;
    END IF;
    -- Handle INSERT or UPDATE (apply new impact)
    IF TG_OP = 'INSERT' OR TG_OP = 'UPDATE' THEN
        
        -- Default to 0 values if row doesn't exist for standard denominations before adding/subtracting
        IF NEW.type IN ('IN', 'CLOSE_ENTRY', 'OUT', 'SWAP') THEN
            INSERT INTO public.cash_box_inventory (box_id, denomination, quantity)
            SELECT NEW.box_id, unnest(ARRAY[500,200,100,50,20,10,5,2,1,0.50,0.20,0.10,0.05,0.02,0.01]::numeric[]), 0
            ON CONFLICT (box_id, denomination) DO NOTHING;
        END IF;
        IF NEW.type IN ('IN', 'CLOSE_ENTRY') AND NEW.breakdown IS NOT NULL THEN
            FOR key_val, qty IN SELECT * FROM jsonb_each_text(NEW.breakdown)
            LOOP
                denom := key_val::numeric;
                qty := qty::numeric;
                UPDATE public.cash_box_inventory 
                SET quantity = quantity + qty
                WHERE box_id = NEW.box_id AND denomination = denom;
            END LOOP;
            
        ELSIF NEW.type = 'OUT' AND NEW.breakdown IS NOT NULL THEN
            FOR key_val, qty IN SELECT * FROM jsonb_each_text(NEW.breakdown)
            LOOP
                denom := key_val::numeric;
                qty := qty::numeric;
                UPDATE public.cash_box_inventory 
                SET quantity = quantity - qty
                WHERE box_id = NEW.box_id AND denomination = denom;
            END LOOP;
            
        ELSIF NEW.type = 'SWAP' AND NEW.breakdown IS NOT NULL THEN
            -- Apply 'in'
            IF NEW.breakdown ? 'in' THEN
                FOR key_val, qty IN SELECT * FROM jsonb_each_text(NEW.breakdown->'in')
                LOOP
                    denom := key_val::numeric;
                    qty := qty::numeric;
                    UPDATE public.cash_box_inventory 
                    SET quantity = quantity + qty
                    WHERE box_id = NEW.box_id AND denomination = denom;
                END LOOP;
            END IF;
            -- Apply 'out'
            IF NEW.breakdown ? 'out' THEN
                FOR key_val, qty IN SELECT * FROM jsonb_each_text(NEW.breakdown->'out')
                LOOP
                    denom := key_val::numeric;
                    qty := qty::numeric;
                    UPDATE public.cash_box_inventory 
                    SET quantity = quantity - qty
                    WHERE box_id = NEW.box_id AND denomination = denom;
                END LOOP;
            END IF;
        ELSIF NEW.type = 'ADJUSTMENT' AND NEW.breakdown IS NOT NULL THEN
            -- For Arqueo (Adjustments), the breakdown IS the new absolute state of the box
            -- First, ensure all default denominations exist for this box setting them to 0
            INSERT INTO public.cash_box_inventory (box_id, denomination, quantity)
            SELECT NEW.box_id, unnest(ARRAY[500,200,100,50,20,10,5,2,1,0.50,0.20,0.10,0.05,0.02,0.01]::numeric[]), 0
            ON CONFLICT (box_id, denomination) DO UPDATE SET quantity = 0;
            
            -- Then, update with the specific counts from the Arqueo
            FOR key_val, qty IN SELECT * FROM jsonb_each_text(NEW.breakdown)
            LOOP
                denom := key_val::numeric;
                qty := qty::numeric;
                UPDATE public.cash_box_inventory 
                SET quantity = qty
                WHERE box_id = NEW.box_id AND denomination = denom;
            END LOOP;
        END IF;
    END IF;
    -- Return appropriately
    IF TG_OP = 'DELETE' THEN
        RETURN OLD;
    END IF;
    RETURN NEW;
END;

DECLARE
    v_articulo_id integer;
    v_notas text;
    v_existing_units numeric;
    v_new_total_units numeric;
    v_delta numeric;
BEGIN
    v_articulo_id := (v_prod->>'articulo_id')::integer;
    v_notas := COALESCE(v_prod->>'notas', '');
    v_new_total_units := (v_prod->>'unidades')::numeric;
    -- Calculamos cuántas unidades YA TENEMOS en la base de datos para este ticket/plato
    -- Usamos 'IS NOT DISTINCT FROM' para tratar los IDs nulos correctamente
    SELECT COALESCE(SUM(unidades), 0) INTO v_existing_units
    FROM public.kds_order_lines
    WHERE id_ticket_tpv IS NOT DISTINCT FROM v_id_ticket
      AND articulo_id = v_articulo_id
      AND notas IS NOT DISTINCT FROM v_notas;
    v_delta := v_new_total_units - v_existing_units;
    -- SOLO insertamos si hay unidades ADICIONALES (Delta > 0)
    IF v_delta > 0 THEN
        INSERT INTO public.kds_order_lines (
            order_id, producto_nombre, unidades, notas, articulo_id, id_ticket_tpv, mesa, numero_documento, estado
        )
        VALUES (
            v_kds_order_id, v_prod->>'nombre', v_delta, v_notas, v_articulo_id, v_id_ticket, v_mesa, v_num_doc, 'pendiente'
        );
    END IF;
END;

DECLARE
    v_total_cost NUMERIC := 0;
    v_user record;
    v_hours NUMERIC;
    v_daily_contracted NUMERIC;
    v_reg_price NUMERIC;
    v_over_price NUMERIC;
BEGIN
    -- Iteramos sobre los perfiles para calcular el coste diario
    FOR v_user IN SELECT id, role, contracted_hours_weekly, regular_cost_per_hour, overtime_cost_per_hour FROM public.profiles LOOP
        v_daily_contracted := COALESCE(v_user.contracted_hours_weekly, 0) / 5.0;
        v_reg_price := COALESCE(v_user.regular_cost_per_hour, 0);
        v_over_price := COALESCE(v_user.overtime_cost_per_hour, v_reg_price);

        -- Obtenemos y redondeamos las horas trabajadas en la fecha objetivo para este usuario
        SELECT COALESCE(SUM(public.fn_calculate_rounded_hours(total_hours)), 0)
        INTO v_hours
        FROM public.time_logs
        WHERE user_id = v_user.id AND DATE(clock_in) = p_target_date;

        -- Lógica de cálculo de coste (idéntica al frontend)
        IF v_user.role = 'manager' THEN
            v_total_cost := v_total_cost + (v_daily_contracted * v_reg_price) + (v_hours * v_over_price);
        ELSE
            IF v_hours > 0 THEN
                IF v_hours > v_daily_contracted THEN
                    v_total_cost := v_total_cost + (v_daily_contracted * v_reg_price) + ((v_hours - v_daily_contracted) * v_over_price);
                ELSE
                    v_total_cost := v_total_cost + (v_hours * v_reg_price);
                END IF;
            END IF;
        END IF;
    END LOOP;

    RETURN v_total_cost;
END;

DECLARE
    v_group_id UUID := gen_random_uuid();
    v_out_total NUMERIC := 0;
    v_in_total NUMERIC := 0;
    v_key TEXT;
    v_val TEXT;
BEGIN
    -- Calcular totales de entrada y salida
    FOR v_key, v_val IN SELECT * FROM jsonb_each_text(p_out_breakdown) LOOP
        v_out_total := v_out_total + (v_key::NUMERIC * v_val::INT);
    END LOOP;
    FOR v_key, v_val IN SELECT * FROM jsonb_each_text(p_in_breakdown) LOOP
        v_in_total := v_in_total + (v_key::NUMERIC * v_val::INT);
    END LOOP;
    -- 1. Pierna de SALIDA del origen (Entrada al destino)
    IF v_out_total > 0 THEN
        INSERT INTO public.treasury_log (
            box_id, to_box_id, type, amount, breakdown, user_id, notes, exchange_group_id
        ) VALUES (
            p_origin_box_id, p_dest_box_id, 'EXCHANGE', v_out_total, p_out_breakdown, 
            p_user_id, COALESCE(p_notes, 'Intercambio: Sale de origen'), v_group_id
        );
    END IF;
    -- 2. Pierna de ENTRADA al origen (Salida del destino)
    IF v_in_total > 0 THEN
        INSERT INTO public.treasury_log (
            box_id, to_box_id, type, amount, breakdown, user_id, notes, exchange_group_id
        ) VALUES (
            p_dest_box_id, p_origin_box_id, 'EXCHANGE', v_in_total, p_in_breakdown, 
            p_user_id, COALESCE(p_notes, 'Intercambio: Entra a origen'), v_group_id
        );
    END IF;
END;

