DECLARE
    v_start date;
    v_end date;
    v_dim int;
    d date;
    v_user record;
    v_day_fixed numeric;
    v_day_ot numeric;
    v_total_fixed numeric := 0;
    v_total_ot numeric := 0;
    v_by_date jsonb := '{}'::jsonb;
    v_sum_day numeric;
BEGIN
    IF NOT public.is_manager_or_admin() THEN
        RAISE EXCEPTION 'forbidden';
    END IF;

    v_start := make_date(p_year, p_month, 1);
    v_end := (date_trunc('month', v_start::timestamp) + interval '1 month - 1 day')::date;
    v_dim := v_end - v_start + 1;

    d := v_start;
    WHILE d <= v_end LOOP
        v_day_fixed := 0;
        v_day_ot := 0;

        FOR v_user IN
            SELECT p.id AS uid
            FROM public.profiles p
            WHERE COALESCE(p.joining_date, DATE '2000-01-01') <= d
              AND (p_user_id IS NULL OR p.id = p_user_id)
        LOOP
            v_day_fixed := v_day_fixed + public.fn_labor_fixed_day_for_user(v_user.uid, d);
            v_day_ot := v_day_ot + COALESCE(public.fn_labor_overtime_allocated_day(v_user.uid, d), 0);
        END LOOP;

        v_sum_day := round(v_day_fixed + v_day_ot, 2);
        v_total_fixed := v_total_fixed + v_day_fixed;
        v_total_ot := v_total_ot + v_day_ot;

        v_by_date := v_by_date || jsonb_build_object(
            to_char(d, 'YYYY-MM-DD'),
            jsonb_build_object(
                'total', v_sum_day,
                'fixed', round(v_day_fixed, 2),
                'overtime', round(v_day_ot, 2)
            )
        );

        d := d + 1;
    END LOOP;

    RETURN jsonb_build_object(
        'year', p_year,
        'month', p_month,
        'daysInMonth', v_dim,
        'totalFixed', round(v_total_fixed, 2),
        'totalOvertime', round(v_total_ot, 2),
        'totalCost', round(v_total_fixed + v_total_ot, 2),
        'byDate', v_by_date
    );
END;

declare
  v_week_start date;
begin
  -- Normaliza a lunes (inicio ISO week)
  v_week_start := public.get_iso_week_start(p_week_start);

  perform public.fn_recalc_and_propagate_snapshots(p_user_id, v_week_start);

  return jsonb_build_object(
    'success', true,
    'userId', p_user_id,
    'fromWeekStart', v_week_start::text,
    'message', 'Recálculo parcial completado (1 empleado desde semana indicada).'
  );
end;

DECLARE
  v_caller_role text;
  v_count integer;
BEGIN
  IF p_user_ids IS NULL OR cardinality(p_user_ids) = 0 THEN
    RETURN 0;
  END IF;

  SELECT role INTO v_caller_role
  FROM public.profiles
  WHERE id = auth.uid();

  IF v_caller_role IS NULL THEN
    RAISE EXCEPTION 'not_authenticated';
  END IF;

  IF v_caller_role NOT IN ('manager', 'admin', 'supervisor') THEN
    RAISE EXCEPTION 'forbidden';
  END IF;

  INSERT INTO public.user_notifications (
    user_id, type, title, body, action_url, entity_type, entity_id
  )
  SELECT
    uid,
    p_type,
    p_title,
    NULLIF(trim(both from coalesce(p_body, '')), ''),
    p_action_url,
    p_entity_type,
    p_entity_id
  FROM unnest(p_user_ids) AS uid
  WHERE uid IS NOT NULL;

  GET DIAGNOSTICS v_count = ROW_COUNT;
  RETURN v_count;
END;

DECLARE
  i jsonb;
  v_old_id text;
  v_new_ids text[];
  v_old_ids text[];
  v_old_mesa jsonb;
BEGIN
  NEW.ultima_actualizacion := now();
  IF NEW.radiografia_completa IS NULL THEN
    NEW.radiografia_completa := '[]'::jsonb;
  END IF;

  IF OLD.radiografia_completa IS NULL THEN
    OLD.radiografia_completa := '[]'::jsonb;
  END IF;

  -- Procesar deltas desde snapshot (idempotente)
  FOR i IN SELECT * FROM jsonb_array_elements(NEW.radiografia_completa)
  LOOP
    PERFORM public.fn_calculate_and_insert_delta(
      i->>'id_ticket',
      i->>'mesa',
      i->>'notas_comanda',
      i->'productos',
      i->>'numero_documento',
      i->>'nombre_cliente'
    );
  END LOOP;

  -- Tickets que estaban en OLD pero ya no aparecen en NEW:
  -- emitir delta con productos [] para cancelar pendientes (sin cerrar comandas).
  SELECT COALESCE(
    array_agg(DISTINCT (x->>'id_ticket'))
      FILTER (WHERE (x->>'id_ticket') IS NOT NULL AND btrim(x->>'id_ticket') <> ''),
    ARRAY[]::text[]
  )
  INTO v_new_ids
  FROM jsonb_array_elements(NEW.radiografia_completa) x;

  SELECT COALESCE(
    array_agg(DISTINCT (x->>'id_ticket'))
      FILTER (WHERE (x->>'id_ticket') IS NOT NULL AND btrim(x->>'id_ticket') <> ''),
    ARRAY[]::text[]
  )
  INTO v_old_ids
  FROM jsonb_array_elements(OLD.radiografia_completa) x;

  FOREACH v_old_id IN ARRAY v_old_ids
  LOOP
    IF NOT (v_old_id = ANY(v_new_ids)) THEN
      SELECT elem INTO v_old_mesa
      FROM jsonb_array_elements(OLD.radiografia_completa) AS t(elem)
      WHERE (elem->>'id_ticket') IS NOT DISTINCT FROM v_old_id
      LIMIT 1;

      IF v_old_mesa IS NOT NULL THEN
        PERFORM public.fn_calculate_and_insert_delta(
          v_old_mesa->>'id_ticket',
          v_old_mesa->>'mesa',
          v_old_mesa->>'notas_comanda',
          '[]'::jsonb,
          v_old_mesa->>'numero_documento',
          v_old_mesa->>'nombre_cliente'
        );
      END IF;
    END IF;
  END LOOP;

  RETURN NEW;
END;

