declare
  v_week_start date;
  v_user_id uuid;
  v_count int := 0;
begin
  v_week_start := public.get_iso_week_start(p_week_start);

  -- Recalcular solo usuarios con actividad o snapshots desde esa semana
  for v_user_id in
    (
      select distinct p.id
      from public.profiles p
      where exists (
        select 1
        from public.time_logs tl
        where tl.user_id = p.id
          and (tl.clock_in at time zone 'Europe/Madrid')::date >= v_week_start
      )
      or exists (
        select 1
        from public.weekly_snapshots ws
        where ws.user_id = p.id
          and ws.week_start >= v_week_start
      )
    )
  loop
    perform public.fn_recalc_and_propagate_snapshots(v_user_id, v_week_start);
    v_count := v_count + 1;
  end loop;

  return jsonb_build_object(
    'success', true,
    'fromWeekStart', v_week_start::text,
    'usersRecalculated', v_count,
    'message', 'Recálculo parcial completado (todos los empleados desde semana indicada).'
  );
end;

DECLARE
  v_total numeric;
  v_days integer;
  v_by_date jsonb;
BEGIN
  IF NOT public.is_manager_or_admin() THEN
    RAISE EXCEPTION 'No autorizado';
  END IF;

  WITH base AS (
    SELECT
      (sm.movement_date AT TIME ZONE 'Europe/Madrid')::date AS day,
      (regexp_match(sm.reference_doc, '^STAFF-([0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12})-'))[1]::uuid AS employee_id,
      public.staff_consumption_movement_amount_eur(
        sm.quantity,
        sm.unit,
        ing.purchase_unit,
        ing.current_price
      ) AS amount
    FROM public.stock_movements sm
    JOIN public.ingredients ing ON ing.id = sm.ingredient_id
    WHERE sm.movement_type = 'WASTE'
      AND sm.reference_doc LIKE 'STAFF-%'
      AND sm.original_description LIKE 'Consumo Personal:%'
      AND (sm.movement_date AT TIME ZONE 'Europe/Madrid')::date >= p_start_date
      AND (sm.movement_date AT TIME ZONE 'Europe/Madrid')::date <= p_end_date
      AND (
        p_user_id IS NULL
        OR (regexp_match(sm.reference_doc, '^STAFF-([0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12})-'))[1]::uuid = p_user_id
      )
  ),
  agg AS (
    SELECT day, SUM(amount)::numeric AS total
    FROM base
    GROUP BY day
  )
  SELECT
    COALESCE(SUM(total), 0)::numeric,
    COALESCE(COUNT(*), 0)::integer,
    COALESCE(
      jsonb_object_agg(
        to_char(day, 'YYYY-MM-DD'),
        jsonb_build_object('total', total)
      ),
      '{}'::jsonb
    )
  INTO v_total, v_days, v_by_date
  FROM agg;

  RETURN jsonb_build_object(
    'totalAmount', v_total,
    'daysInPeriod', v_days,
    'byDate', v_by_date
  );
END;

SELECT
    t.fecha::date AS fecha,
    EXTRACT(HOUR FROM timezone('Europe/Madrid',
        public.fn_parse_ticket_hora_cierre_ts(t.fecha, t.hora_cierre, t.fecha_real)
    ))::int AS hora,
    ROUND(SUM(t.total_documento)::numeric, 2) AS total
FROM public.tickets_marbella t
WHERE t.fecha IS NOT NULL
  AND t.fecha >= p_start_date
  AND t.fecha <= p_end_date
GROUP BY t.fecha::date, EXTRACT(HOUR FROM timezone('Europe/Madrid',
    public.fn_parse_ticket_hora_cierre_ts(t.fecha, t.hora_cierre, t.fecha_real)
))
ORDER BY t.fecha::date, hora;

