DECLARE
  v_bruto numeric := 0;
  v_efectivo numeric := 0;
  v_tarjeta numeric := 0;
  v_pendiente numeric := 0;
  v_cobros_deuda numeric := 0;
  v_recuento integer := 0;
BEGIN
  IF p_date IS NULL THEN
    RAISE EXCEPTION 'get_closing_sales_breakdown: p_date es obligatorio';
  END IF;

  SELECT
    COALESCE(round(sum(t.total_documento)::numeric, 2), 0),
    COALESCE(round(sum(t.cobro_efectivo)::numeric, 2), 0),
    COALESCE(round(sum(t.cobro_tarjeta)::numeric, 2), 0),
    COALESCE(round(sum(t.cobro_pendiente)::numeric, 2), 0),
    COALESCE(count(*) FILTER (WHERE t.total_documento <> 0), 0)::integer
  INTO v_bruto, v_efectivo, v_tarjeta, v_pendiente, v_recuento
  FROM public.tickets_marbella t
  WHERE (t.fecha)::date = p_date
    AND upper(trim(t.numero_documento)) <> 'COMPROBANTE';

  SELECT COALESCE(round(sum(m.amount)::numeric, 2), 0)
  INTO v_cobros_deuda
  FROM public.bdp_cash_movements m
  WHERE m.fecha_negocio = p_date
    AND m.concept_code = 107;

  RETURN jsonb_build_object(
    'total_bruto', v_bruto,
    'total_efectivo', v_efectivo,
    'total_tarjeta', v_tarjeta,
    'total_pendiente', v_pendiente,
    'total_cobros_deuda', v_cobros_deuda,
    'recuento_tickets', v_recuento
  );
END;

DECLARE
  vrec jsonb;
  v_target_qty int;
  v_existing_count int;
  v_delta int;
  vi int;

  v_articulo_id int;
  v_nombre text;
  v_notas text;
  v_notas_n text;

  v_envia_art boolean;
  v_envia_dept boolean;
  v_effective_envia boolean;
  v_departamento_id integer;

  v_last_order_id uuid;
  v_last_order_created timestamptz;
  v_batch_id uuid;
  v_cancel_remaining int;

  r record;
  -- Sentinel INT4 mínimo: no se usa como PLU real; permite equi-join hashable sustituyendo NULL.
  k_sentinel int := -2147483648;
BEGIN
  IF aprods IS NULL THEN
    aprods := '[]'::jsonb;
  END IF;

  DROP TABLE IF EXISTS tmp_fncalcdelta_targets;
  CREATE TEMP TABLE tmp_fncalcdelta_targets (
    articulo_id int NOT NULL,
    notas_n text NOT NULL,
    qty int NOT NULL,
    nombre text,
    PRIMARY KEY (articulo_id, notas_n)
  ) ON COMMIT DROP;

  FOR vrec IN SELECT * FROM jsonb_array_elements(aprods)
  LOOP
    v_target_qty := COALESCE(NULLIF(floor(COALESCE((vrec->>'unidades')::numeric, 0))::int, 0), 0);
    IF v_target_qty <= 0 THEN
      CONTINUE;
    END IF;

    v_nombre := NULLIF(btrim(COALESCE(vrec->>'nombre', '')), '');
    v_notas := COALESCE(vrec->>'notas', '');
    v_notas_n := COALESCE(v_notas, '');
    v_articulo_id := NULLIF((vrec->>'articulo_id')::int, 0);

    IF v_articulo_id IS NULL AND v_nombre IS NOT NULL THEN
      SELECT a.id
      INTO v_articulo_id
      FROM public.bdp_articulos a
      WHERE lower(btrim(a.nombre)) = lower(btrim(v_nombre))
      LIMIT 1;
    END IF;

    -- Lógica de filtrado KDS
    v_effective_envia := FALSE;
    
    -- EXCEPCIÓN PARA PACKS: Si el nombre empieza por '↳ ', forzamos su envío al KDS
    IF v_nombre LIKE '↳ %' THEN
      v_effective_envia := TRUE;
    ELSIF v_articulo_id IS NOT NULL THEN
      SELECT a.envia_a_kds, a.departamento_id
      INTO v_envia_art, v_departamento_id
      FROM public.bdp_articulos a
      WHERE a.id = v_articulo_id
      LIMIT 1;

      IF v_envia_art IS TRUE THEN
        v_effective_envia := TRUE;
      ELSIF v_envia_art IS FALSE THEN
        v_effective_envia := FALSE;
      ELSE
        SELECT d.envia_a_kds
        INTO v_envia_dept
        FROM public.bdp_departamentos d
        WHERE d.id = v_departamento_id
        LIMIT 1;
        v_effective_envia := COALESCE(v_envia_dept, FALSE);
      END IF;
    END IF;

    IF v_effective_envia IS NOT TRUE THEN
      CONTINUE;
    END IF;

    INSERT INTO tmp_fncalcdelta_targets (articulo_id, notas_n, qty, nombre)
    VALUES (v_articulo_id, v_notas_n, v_target_qty, v_nombre)
    ON CONFLICT (articulo_id, notas_n) DO UPDATE
      SET qty = tmp_fncalcdelta_targets.qty + EXCLUDED.qty,
          nombre = COALESCE(EXCLUDED.nombre, tmp_fncalcdelta_targets.nombre);
  END LOOP;

  SELECT o.id, o.created_at
  INTO v_last_order_id, v_last_order_created
  FROM public.kds_orders o
  WHERE o.id_ticket = aid
    AND o.estado = 'activa'::public.kds_order_status
  ORDER BY o.created_at DESC
  LIMIT 1;

  IF NOT EXISTS (SELECT 1 FROM tmp_fncalcdelta_targets)
     AND NOT EXISTS (
       SELECT 1
       FROM public.kds_order_lines l
       JOIN public.kds_orders o ON o.id = l.kds_order_id
       WHERE o.id_ticket = aid
         AND o.estado = 'activa'::public.kds_order_status
         AND l.estado <> 'cancelado'::public.kds_item_status
     ) THEN
    RETURN;
  END IF;

  IF v_last_order_id IS NULL
     AND EXISTS (SELECT 1 FROM tmp_fncalcdelta_targets t WHERE t.qty > 0) THEN
    INSERT INTO public.kds_orders (id_ticket, mesa, notas_comanda, estado, origen)
    VALUES (aid, amesa, anotas, 'activa', 'TPV')
    RETURNING id, created_at INTO v_last_order_id, v_last_order_created;
  END IF;

  FOR r IN
    SELECT
      COALESCE(t.articulo_id, e.articulo_id) AS articulo_id,
      COALESCE(t.notas_n, e.notas_n) AS notas_n,
      COALESCE(t.qty, 0) AS target_qty,
      COALESCE(e.cnt, 0) AS existing_cnt,
      t.nombre AS nombre_tgt
    FROM tmp_fncalcdelta_targets t
    FULL OUTER JOIN (
      SELECT
        l.articulo_id,
        COALESCE(l.notas, '') AS notas_n,
        COUNT(*)::int AS cnt
      FROM public.kds_order_lines l
      JOIN public.kds_orders o ON o.id = l.kds_order_id
      WHERE o.id_ticket = aid
        AND o.estado = 'activa'::public.kds_order_status
        AND l.estado <> 'cancelado'::public.kds_item_status
      GROUP BY l.articulo_id, COALESCE(l.notas, '')
    ) e ON COALESCE(t.articulo_id, k_sentinel) = COALESCE(e.articulo_id, k_sentinel)
       AND COALESCE(t.notas_n, '') = COALESCE(e.notas_n, '')
    WHERE COALESCE(t.articulo_id, e.articulo_id) IS NOT NULL
  LOOP
    v_articulo_id := r.articulo_id;
    v_notas := r.notas_n;
    v_target_qty := r.target_qty;
    v_existing_count := r.existing_cnt;

    v_delta := COALESCE(v_target_qty, 0) - COALESCE(v_existing_count, 0);

    SELECT a.nombre INTO v_nombre
    FROM public.bdp_articulos a
    WHERE a.id = v_articulo_id
    LIMIT 1;
    IF v_nombre IS NULL THEN
      v_nombre := COALESCE(r.nombre_tgt, 'Sin nombre');
    END IF;

    IF v_delta > 0 THEN
      IF v_last_order_id IS NULL THEN
        INSERT INTO public.kds_orders (id_ticket, mesa, notas_comanda, estado, origen)
        VALUES (aid, amesa, anotas, 'activa', 'TPV')
        RETURNING id, created_at INTO v_last_order_id, v_last_order_created;
      END IF;

      IF now() - v_last_order_created > interval '120 seconds' THEN
        INSERT INTO public.kds_orders (id_ticket, mesa, notas_comanda, estado, origen)
        VALUES (aid, amesa, anotas, 'activa', 'TPV')
        RETURNING id, created_at INTO v_batch_id, v_last_order_created;
        v_last_order_id := v_batch_id;
      END IF;

      FOR vi IN 1..v_delta
      LOOP
        INSERT INTO public.kds_order_lines (
          kds_order_id,
          producto_nombre,
          articulo_id,
          unidades,
          cantidad,
          estado,
          notas,
          mesa,
          numero_documento
        )
        VALUES (
          v_last_order_id,
          v_nombre,
          v_articulo_id,
          1,
          1,
          'pendiente',
          NULLIF(v_notas, ''),
          amesa,
          adoc
        );
      END LOOP;

    ELSIF v_delta < 0 THEN
      v_cancel_remaining := -v_delta;

      UPDATE public.kds_order_lines l
      SET estado = 'cancelado'::public.kds_item_status,
          completed_at = COALESCE(l.completed_at, now())
      WHERE l.id IN (
        SELECT l2.id
        FROM public.kds_order_lines l2
        JOIN public.kds_orders o2 ON o2.id = l2.kds_order_id
        WHERE o2.id_ticket = aid
          AND o2.estado = 'activa'::public.kds_order_status
          AND l2.estado = 'pendiente'::public.kds_item_status
          AND l2.articulo_id IS NOT DISTINCT FROM v_articulo_id
          AND COALESCE(l2.notas, '') IS NOT DISTINCT FROM COALESCE(v_notas, '')
        ORDER BY o2.created_at DESC, l2.created_at DESC
        LIMIT v_cancel_remaining
      );
    END IF;
  END LOOP;
END;

DECLARE
  v_sales_positive numeric := 0;
  v_sales_refunds numeric := 0;
  v_sales_net numeric := 0;
  v_sales_gross_positive numeric := 0;
  v_sales_gross_net numeric := 0;

  v_purchases_total numeric := 0;
  v_payroll_total numeric := 0;
  v_rent_total numeric := 0;
  v_overtime_total numeric := 0;
  v_pyg_expenses_total numeric := 0;
  v_pyg_net numeric := 0;

  v_cash_in numeric := 0;
  v_cash_out numeric := 0;
  v_cash_bank_transfer_out numeric := 0;
  v_cash_adjustment numeric := 0;
  v_cash_swap numeric := 0;
  v_cash_net numeric := 0;

  v_meta jsonb;
  v_pyg jsonb;
  v_cashflow jsonb;
BEGIN
  IF p_start_date IS NULL OR p_end_date IS NULL THEN
    RAISE EXCEPTION 'get_financial_statement: p_start_date y p_end_date son obligatorios';
  END IF;

  IF p_end_date < p_start_date THEN
    RAISE EXCEPTION 'get_financial_statement: rango inválido (% > %)', p_start_date, p_end_date;
  END IF;

  IF NOT public.is_manager_or_admin() THEN
    RAISE EXCEPTION 'forbidden';
  END IF;

  -- PY&L (Devengo): Ventas desde tickets_marbella por fecha (Fuente de verdad).
  SELECT
    COALESCE(SUM(CASE WHEN t.total_documento > 0 THEN ROUND(t.total_documento / 1.10, 2) ELSE 0 END), 0),
    COALESCE(SUM(CASE WHEN t.total_documento < 0 THEN ROUND(t.total_documento / 1.10, 2) ELSE 0 END), 0),
    COALESCE(SUM(ROUND(t.total_documento / 1.10, 2)), 0),
    COALESCE(SUM(CASE WHEN t.total_documento > 0 THEN t.total_documento ELSE 0 END), 0),
    COALESCE(SUM(t.total_documento), 0)
  INTO v_sales_positive, v_sales_refunds, v_sales_net, v_sales_gross_positive, v_sales_gross_net
  FROM public.tickets_marbella t
  WHERE t.fecha >= p_start_date
    AND t.fecha <= p_end_date;

  -- PY&L (Devengo): Compras verificadas (no "processing").
  SELECT COALESCE(SUM(
    CASE
      WHEN pi.base_amount IS NOT NULL AND pi.base_amount > 0
        THEN pi.base_amount
      ELSE ROUND(pi.total_amount / 1.10, 2)
    END
  ), 0)
  INTO v_purchases_total
  FROM public.purchase_invoices pi
  WHERE pi.invoice_date IS NOT NULL
    AND pi.total_amount IS NOT NULL
    AND pi.invoice_date >= p_start_date
    AND pi.invoice_date <= p_end_date
    AND pi.status IN ('mapped', 'completed');

  -- PY&L (Devengo): Nóminas prorrateadas por días solapados del periodo PDF.
  SELECT COALESCE(SUM(
    pmt.total_company_cost * (
      (LEAST(p_end_date, pmt.period_end) - GREATEST(p_start_date, pmt.period_start) + 1)::numeric /
      (pmt.period_end - pmt.period_start + 1)::numeric
    )
  ), 0)
  INTO v_payroll_total
  FROM public.payroll_monthly_totals pmt
  WHERE pmt.period_start <= p_end_date
    AND pmt.period_end >= p_start_date;

  -- PY&L (Devengo): Alquiler prorrateado por días del mes en el rango.
  SELECT COALESCE(SUM(
    fmc.amount * (
      (LEAST(p_end_date, (date_trunc('month', gs.month) + INTERVAL '1 month - 1 day')::date) -
       GREATEST(p_start_date, date_trunc('month', gs.month)::date) + 1)::numeric /
      EXTRACT(DAY FROM (date_trunc('month', gs.month) + INTERVAL '1 month - 1 day'))::numeric
    )
  ), 0)
  INTO v_rent_total
  FROM public.fixed_monthly_costs fmc,
  LATERAL generate_series(
    date_trunc('month', p_start_date::timestamp),
    date_trunc('month', p_end_date::timestamp),
    INTERVAL '1 month'
  ) AS gs(month)
  WHERE lower(fmc.name) = 'alquiler'
    AND (fmc.active_to IS NULL OR fmc.active_to >= p_start_date)
    AND fmc.active_from <= p_end_date;

  -- PY&L (Devengo): Horas extras prorrateadas por días de semana solapados (total_cost).
  SELECT COALESCE(SUM(
    ws.total_cost * (
      (LEAST(p_end_date, ws.week_end) - GREATEST(p_start_date, ws.week_start) + 1)::numeric /
      (ws.week_end - ws.week_start + 1)::numeric
    )
  ), 0)
  INTO v_overtime_total
  FROM public.weekly_snapshots ws
  WHERE ws.week_start <= p_end_date
    AND ws.week_end >= p_start_date
    AND ws.total_cost > 0;

  v_pyg_expenses_total := COALESCE(v_purchases_total, 0)
    + COALESCE(v_payroll_total, 0)
    + COALESCE(v_rent_total, 0)
    + COALESCE(v_overtime_total, 0);
  v_pyg_net := COALESCE(v_sales_net, 0) - COALESCE(v_pyg_expenses_total, 0);

  -- CASH FLOW (Caja): treasury_log por created_at convertido a fecha Europe/Madrid.
  SELECT
    COALESCE(SUM(CASE WHEN tl.type IN ('IN', 'CLOSE_ENTRY') THEN tl.amount ELSE 0 END), 0),
    COALESCE(SUM(CASE WHEN tl.type = 'OUT' AND NOT (COALESCE(tl.notes,'') ILIKE '%banc%') THEN tl.amount ELSE 0 END), 0),
    COALESCE(SUM(CASE WHEN tl.type = 'OUT' AND (COALESCE(tl.notes,'') ILIKE '%banc%') THEN tl.amount ELSE 0 END), 0),
    COALESCE(SUM(CASE WHEN tl.type = 'ADJUSTMENT' THEN tl.amount ELSE 0 END), 0),
    COALESCE(SUM(CASE WHEN tl.type = 'SWAP' THEN tl.amount ELSE 0 END), 0)
  INTO v_cash_in, v_cash_out, v_cash_bank_transfer_out, v_cash_adjustment, v_cash_swap
  FROM public.treasury_log tl
  WHERE ((tl.created_at AT TIME ZONE 'Europe/Madrid')::date) >= p_start_date
    AND ((tl.created_at AT TIME ZONE 'Europe/Madrid')::date) <= p_end_date;

  v_cash_net := COALESCE(v_cash_in, 0) - COALESCE(v_cash_out, 0);

  v_meta := jsonb_build_object(
    'startDate', p_start_date,
    'endDate', p_end_date,
    'generatedAt', now(),
    'timezone', 'Europe/Madrid',
    'sources', jsonb_build_object(
      'accrualIncome', 'tickets_marbella(total_documento) by fecha',
      'accrualPurchases', 'purchase_invoices(total_amount) by invoice_date, status IN (mapped, completed)',
      'accrualPayroll', 'payroll_monthly_totals(total_company_cost) prorated by overlapping days',
      'accrualRent', 'fixed_monthly_costs(name=alquiler) prorated by calendar days per month',
      'accrualOvertime', 'weekly_snapshots(total_cost) prorated by overlapping week days',
      'cashFlow', 'treasury_log by created_at Europe/Madrid date'
    )
  );

  v_pyg := jsonb_build_object(
    'income', jsonb_build_object(
      'total', v_sales_net,
      'gross_total', v_sales_gross_positive,
      'gross_net', v_sales_gross_net,
      'lines', jsonb_build_array(
        jsonb_build_object('key', 'sales_positive', 'label', 'Ventas (positivas)', 'amount', v_sales_positive),
        jsonb_build_object('key', 'refunds', 'label', 'Devoluciones (negativas)', 'amount', v_sales_refunds)
      )
    ),
    'expenses', jsonb_build_object(
      'total', v_pyg_expenses_total,
      'lines', jsonb_build_array(
        jsonb_build_object('key', 'purchases_invoices', 'label', 'Compras verificadas', 'amount', v_purchases_total),
        jsonb_build_object('key', 'payroll_total', 'label', 'Nóminas (coste empresa)', 'amount', v_payroll_total),
        jsonb_build_object('key', 'overtime', 'label', 'Horas extras', 'amount', v_overtime_total),
        jsonb_build_object('key', 'rent_monthly', 'label', 'Alquiler', 'amount', v_rent_total)
      )
    ),
    'net', v_pyg_net
  );

  v_cashflow := jsonb_build_object(
    'inflows', jsonb_build_object(
      'total', v_cash_in,
      'lines', jsonb_build_array(
        jsonb_build_object('key', 'treasury_in', 'label', 'Entradas (IN + CLOSE_ENTRY)', 'amount', v_cash_in)
      )
    ),
    'outflows', jsonb_build_object(
      'total', v_cash_out,
      'lines', jsonb_build_array(
        jsonb_build_object('key', 'treasury_out', 'label', 'Salidas (OUT)', 'amount', v_cash_out)
      )
    ),
    'other', jsonb_build_object(
      'bankTransferOut', v_cash_bank_transfer_out,
      'adjustment', v_cash_adjustment,
      'swap', v_cash_swap
    ),
    'net', v_cash_net
  );

  RETURN jsonb_build_object(
    'meta', v_meta,
    'pyg', v_pyg,
    'cashFlow', v_cashflow,
    'reconciliation', jsonb_build_object(
      'accrualNet', v_pyg_net,
      'cashNet', v_cash_net,
      'delta', (v_pyg_net - v_cash_net)
    )
  );
END;

