DECLARE
  v_event_id uuid;
  v_event_name text;
  v_event_date date;
  v_event_time time;
  v_event_active boolean;
  v_enabled_ids text[];
  v_client_edit boolean;
  v_submitted_at timestamptz;
  v_reservation_id uuid;
  v_guest_count integer;
  v_event_ts timestamptz;
  v_order_id uuid;
  v_responsible text;
  v_total numeric := 0;
  v_item jsonb;
  v_pid text;
  v_qty integer;
  v_name text;
  v_price numeric;
  v_category text;
  v_base_name text;
  v_base_price numeric;
  v_is_half boolean;
  v_line_notes text;
  v_half_notes text;
  v_items_out jsonb := '[]'::jsonb;
  v_any boolean := false;
  v_body text;
  v_date_line text;
  v_kind_line text;
  y int; mo int; d int; hh int; mi int;
  v_dow int;
  v_mon int;
  v_day_name text;
  v_mon_name text;
  v_webhook_url text;
  v_record_json jsonb;
BEGIN
  IF p_token IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'token_requerido'); END IF;

  SELECT e.id, e.name, e.event_date, e.event_time, e.is_active,
    e.enabled_product_ids, e.client_edit_enabled, e.client_order_submitted_at,
    e.reservation_id, e.guest_count
  INTO v_event_id, v_event_name, v_event_date, v_event_time, v_event_active,
    v_enabled_ids, v_client_edit, v_submitted_at,
    v_reservation_id, v_guest_count
  FROM public.events e WHERE e.client_edit_token = p_token LIMIT 1;

  IF v_event_id IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'not_found'); END IF;
  IF v_submitted_at IS NOT NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'already_submitted'); END IF;
  IF v_client_edit IS DISTINCT FROM true THEN RETURN jsonb_build_object('ok', false, 'error', 'client_edit_disabled'); END IF;
  IF v_event_active IS DISTINCT FROM true THEN RETURN jsonb_build_object('ok', false, 'error', 'event_inactive'); END IF;

  y := EXTRACT(YEAR FROM v_event_date)::int;
  mo := EXTRACT(MONTH FROM v_event_date)::int;
  d := EXTRACT(DAY FROM v_event_date)::int;
  hh := EXTRACT(HOUR FROM v_event_time)::int;
  mi := EXTRACT(MINUTE FROM v_event_time)::int;
  v_event_ts := make_timestamptz(y, mo, d, hh, mi, 0, 'Europe/Madrid');
  IF v_event_ts < now() THEN RETURN jsonb_build_object('ok', false, 'error', 'event_past'); END IF;

  IF jsonb_typeof(p_items) IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'items_invalidos'; END IF;

  FOR v_item IN SELECT * FROM jsonb_array_elements(p_items) LOOP
    v_pid := trim(coalesce(v_item->>'product_id', ''));
    v_qty := NULLIF(trim(coalesce(v_item->>'quantity', '')), '')::int;
    v_line_notes := NULLIF(trim(coalesce(v_item->>'notes', '')), '');
    v_is_half := coalesce((v_item->>'is_half')::boolean, false)
      OR lower(coalesce(v_line_notes, '')) IN ('1/2', '½', 'medio', 'mitad', 'half');

    IF v_pid = '' THEN RAISE EXCEPTION 'product_id_requerido'; END IF;
    IF v_qty IS NULL OR v_qty <= 0 THEN RAISE EXCEPTION 'quantity_invalida'; END IF;
    IF v_enabled_ids IS NOT NULL AND NOT (v_pid = ANY(v_enabled_ids)) THEN
      RAISE EXCEPTION 'producto_no_permitido: %', v_pid;
    END IF;

    SELECT rp.name, rp.price, rp.category INTO v_name, v_price, v_category
    FROM public.fn_resolve_event_order_product(v_pid) rp LIMIT 1;
    IF v_name IS NULL OR v_name = '' OR v_price IS NULL THEN
      RAISE EXCEPTION 'producto_no_disponible: %', v_pid;
    END IF;

    v_base_name := v_name;
    v_base_price := v_price;

    INSERT INTO public.event_products (product_id, name, price, category, is_active)
    VALUES (v_pid, v_base_name, v_base_price, v_category, true)
    ON CONFLICT (product_id) DO UPDATE SET name = EXCLUDED.name, price = EXCLUDED.price,
      category = COALESCE(EXCLUDED.category, public.event_products.category),
      is_active = true, updated_at = now();

    SELECT a.out_name, a.out_price, a.out_notes
    INTO v_name, v_price, v_half_notes
    FROM public.fn_event_order_apply_racion(v_pid, v_base_name, v_base_price, v_is_half) a;

    v_line_notes := coalesce(v_half_notes, v_line_notes);

    v_any := true;
    v_total := v_total + (v_price * v_qty);
    v_items_out := v_items_out || jsonb_build_array(
      jsonb_build_object(
        'product_id', v_pid,
        'name', v_name,
        'quantity', v_qty,
        'unit_price', v_price,
        'notes', v_line_notes,
        'is_half', v_is_half
      )
    );
  END LOOP;

  IF v_any IS DISTINCT FROM true THEN RAISE EXCEPTION 'items_vacios'; END IF;
  v_responsible := coalesce(nullif(trim(v_event_name), ''), 'Cliente');

  SELECT o.id INTO v_order_id FROM public.event_orders o
  WHERE o.event_id = v_event_id AND o.status IN ('pending', 'confirmed')
  ORDER BY CASE WHEN o.status = 'confirmed' THEN 0 ELSE 1 END, o.created_at ASC LIMIT 1;

  IF v_order_id IS NULL THEN
    INSERT INTO public.event_orders (event_id, responsible_name, items, total_amount, notes, status)
    VALUES (v_event_id, v_responsible, v_items_out, v_total, NULLIF(trim(coalesce(p_notes, '')), ''), 'pending')
    RETURNING id INTO v_order_id;
  ELSE
    UPDATE public.event_orders SET items = v_items_out, total_amount = v_total,
      notes = COALESCE(NULLIF(trim(coalesce(p_notes, '')), ''), notes),
      responsible_name = v_responsible, status = 'pending'
    WHERE id = v_order_id;
  END IF;

  UPDATE public.events SET
    client_edit_enabled = false,
    client_order_submitted_at = now(),
    filled_by = COALESCE(filled_by, 'client'),
    updated_at = now()
  WHERE id = v_event_id;

  v_dow := EXTRACT(DOW FROM v_event_date)::int;
  v_mon := EXTRACT(MONTH FROM v_event_date)::int;
  v_day_name := CASE v_dow
    WHEN 0 THEN 'Domingo' WHEN 1 THEN 'Lunes' WHEN 2 THEN 'Martes' WHEN 3 THEN 'Miércoles'
    WHEN 4 THEN 'Jueves' WHEN 5 THEN 'Viernes' ELSE 'Sábado'
  END;
  v_mon_name := CASE v_mon
    WHEN 1 THEN 'enero' WHEN 2 THEN 'febrero' WHEN 3 THEN 'marzo' WHEN 4 THEN 'abril'
    WHEN 5 THEN 'mayo' WHEN 6 THEN 'junio' WHEN 7 THEN 'julio' WHEN 8 THEN 'agosto'
    WHEN 9 THEN 'septiembre' WHEN 10 THEN 'octubre' WHEN 11 THEN 'noviembre' ELSE 'diciembre'
  END;
  v_date_line := v_day_name || ' ' || d::text || ' ' || v_mon_name
    || ' · ' || lpad(hh::text, 2, '0') || ':' || lpad(mi::text, 2, '0');
  v_kind_line := CASE
    WHEN v_reservation_id IS NOT NULL THEN 'Reserva con pedido'
    ELSE 'Pedido'
  END;
  v_body := trim(coalesce(v_event_name, 'Cliente'))
    || E'\n' || v_date_line
    || E'\n' || v_kind_line;

  INSERT INTO public.user_notifications (
    user_id, type, title, body, action_url, entity_type, entity_id
  )
  SELECT
    p.id,
    'client_order_submitted',
    'Nuevo pedido recibido',
    v_body,
    '/staff/reservas?eventId=' || v_event_id::text,
    'event',
    v_event_id
  FROM public.profiles p
  WHERE lower(trim(p.first_name)) IN (
    'alba',
    'hernan',
    'pere',
    'hector'
  );

  SELECT value INTO v_webhook_url FROM public.app_settings
  WHERE key = 'push_webhook_url';

  IF v_webhook_url IS NOT NULL THEN
    v_record_json := jsonb_build_object(
      'type', 'INSERT',
      'table', 'events',
      'kind', 'client_order_submitted',
      'record', jsonb_build_object(
        'id', v_event_id,
        'customer_name', coalesce(v_event_name, 'Cliente'),
        'event_date', v_event_date::text,
        'event_time', to_char(v_event_time, 'HH24:MI'),
        'guest_count', v_guest_count,
        'kind_line', v_kind_line,
        'reservation_id', v_reservation_id
      )
    );

    PERFORM net.http_post(
      v_webhook_url,
      v_record_json,
      NULL,
      jsonb_build_object(
        'Content-Type', 'application/json',
        'X-Pgnet', 'true'
      )
    );
  END IF;

  RETURN jsonb_build_object(
    'ok', true, 'id', v_order_id, 'event_id', v_event_id,
    'responsible_name', v_responsible, 'items', v_items_out,
    'total_amount', v_total, 'status', 'pending',
    'client_edit_closed', true, 'client_order_submitted', true
  );
END;

DECLARE
  v_nombre text := trim(COALESCE(p_datos->>'nombre', p_datos->>'name', ''));
BEGIN
  IF p_accion IN ('buscar', 'listar', 'consultar') THEN
    IF v_nombre <> '' THEN
      RETURN COALESCE((
        SELECT jsonb_agg(row_to_json(t)::jsonb ORDER BY t.name)
        FROM (
          SELECT id, name, phone, email, contact_person, image_url
          FROM public.suppliers
          WHERE name ILIKE '%' || v_nombre || '%'
          LIMIT 5
        ) t
      ), jsonb_build_object('error', 'proveedor_no_encontrado', 'nombre_buscado', v_nombre));
    ELSE
      RETURN COALESCE((
        SELECT jsonb_agg(row_to_json(t)::jsonb ORDER BY t.name)
        FROM (
          SELECT id, name, phone, email, contact_person
          FROM public.suppliers
          ORDER BY name
        ) t
      ), '[]'::jsonb);
    END IF;
  END IF;
  RETURN jsonb_build_object('error', 'accion_no_soportada', 'acciones_validas', '["buscar","listar"]');
END;

DECLARE
  v_role    text := public.current_employee_role();
  v_fecha   date := COALESCE((p_datos->>'fecha')::date, CURRENT_DATE);
BEGIN
  -- Consulta: resumen del día
  IF p_accion IN ('consultar', 'listar', 'ver', 'resumen') THEN
    IF v_role NOT IN ('manager','admin','supervisor','chef') THEN
      RETURN jsonb_build_object('error', 'permiso_denegado', 'detalle', 'Solo gerencia puede ver el resumen de consumos');
    END IF;
    RETURN COALESCE((
      SELECT jsonb_agg(row_to_json(t)::jsonb ORDER BY t.consumed_at DESC)
      FROM (
        SELECT
          sc.id,
          sc.consumed_at,
          trim(concat_ws(' ', p.first_name, p.last_name)) AS empleado,
          r.name AS receta,
          sc.quantity,
          sc.is_half
        FROM public.staff_consumption sc
        JOIN public.profiles p ON p.id = sc.employee_id
        JOIN public.recipes r ON r.id = sc.recipe_id
        WHERE sc.consumed_at::date = v_fecha
        ORDER BY sc.consumed_at DESC
        LIMIT 100
      ) t
    ), jsonb_build_object('fecha', v_fecha, 'consumos', '[]'));
  END IF;
  RETURN jsonb_build_object('error', 'accion_no_soportada', 'acciones_validas', '["consultar","listar"]');
END;

DECLARE
  v numeric;
  piece numeric;
  fu text;
  pu text;
BEGIN
  IF p_qty IS NULL THEN
    RETURN NULL;
  END IF;

  v := public.convert_pricing_qty(
    p_qty,
    p_recipe_unit,
    COALESCE(p_purchase_unit, 'ud')
  );
  IF v IS NOT NULL THEN
    RETURN v;
  END IF;

  fu := public.normalize_pricing_unit(p_recipe_unit);
  pu := public.normalize_pricing_unit(COALESCE(p_purchase_unit, 'ud'));

  -- Puente: receta en unidades (ud) y compra en masa o volumen, con precio por pack
  -- que define tamaño por unidad (ej. 1 ud = 330 ml, compra en L).
  IF fu = 'ud'
     AND pu IN ('g', 'kg', 'ml', 'l')
     AND COALESCE(lower(trim(p_supplier_pricing_mode)), '') = 'per_pack'
     AND p_pack_unit_size_qty IS NOT NULL
     AND p_pack_unit_size_qty > 0
     AND p_pack_unit_size_unit IS NOT NULL
     AND trim(p_pack_unit_size_unit) <> '' THEN
    piece := public.convert_pricing_qty(
      p_pack_unit_size_qty,
      p_pack_unit_size_unit,
      COALESCE(p_purchase_unit, 'ud')
    );
    IF piece IS NOT NULL AND piece > 0 THEN
      RETURN p_qty * piece;
    END IF;
  END IF;

  RAISE EXCEPTION
    'Consumo personal: en "%" el ingrediente "%" no se puede convertir de unidad de receta % a unidad de compra %. Si compra por peso o volumen, use g/kg o ml/L en la línea de receta, o configure "precio por pack" con el tamaño por unidad (ej. 330 ml por botella).',
    COALESCE(NULLIF(trim(p_recipe_name), ''), '(producto)'),
    COALESCE(NULLIF(trim(p_ingredient_name), ''), '(ingrediente)'),
    COALESCE(NULLIF(trim(p_recipe_unit), ''), '?'),
    COALESCE(NULLIF(trim(COALESCE(p_purchase_unit, 'ud')), ''), '?')
    USING HINT = 'Revise recipe_ingredients.unit y ingredients.purchase_unit / supplier_pricing_mode / pack_*';
END;

DECLARE
  v_fecha       date  := COALESCE((p_datos->>'fecha')::date, CURRENT_DATE);
  v_user_id     uuid  := (p_datos->>'user_id')::uuid;
  v_nombre      text  := trim(COALESCE(p_datos->>'nombre', ''));
  v_role        text  := public.current_employee_role();
BEGIN
  IF p_accion IN ('consultar', 'listar', 'ver') THEN
    -- staff solo ve su propio turno a menos que se le diga explícitamente otro
    IF v_role = 'staff' AND v_user_id IS NULL THEN
      v_user_id := auth.uid();
    END IF;
    RETURN COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'fecha',        s.date,
        'empleado',     trim(concat_ws(' ', p.first_name, p.last_name)),
        'actividad',    s.activity,
        'hora_inicio',  s.event_start_time,
        'hora_fin',     s.event_end_time,
        'participantes',s.event_participants,
        'categoria',    s.categoria,
        'publicado',    s.is_published
      ) ORDER BY s.date, p.first_name)
      FROM public.shifts s
      JOIN public.profiles p ON p.id = s.user_id
      WHERE s.date = v_fecha
        AND s.is_published = true
        AND (v_user_id IS NULL OR s.user_id = v_user_id)
        AND (v_nombre = '' OR (p.first_name || ' ' || COALESCE(p.last_name,'')) ILIKE '%' || v_nombre || '%')
    ), jsonb_build_object('fecha', v_fecha, 'turnos', '[]', 'nota', 'No hay turnos publicados para esta fecha'));
  END IF;
  RETURN jsonb_build_object('error', 'accion_no_soportada', 'acciones_validas', '["consultar"]');
END;

