DECLARE
  v_nombre   text := lower(trim(COALESCE(p_datos->>'nombre', p_datos->>'name', '')));
  v_receta_id uuid;
  v_recipe_name text;
  v_matches jsonb;
  v_count_all int;
  v_best_match RECORD;
BEGIN
  -- 1. Si no hay acción o es buscar/consultar
  IF p_accion IN ('buscar', 'listar', 'consultar', 'search', 'list', 'get') THEN
    
    -- Listar todas (resumen) si no hay nombre
    IF v_nombre = '' AND p_accion IN ('listar', 'list') THEN
      RETURN COALESCE((
        SELECT jsonb_agg(jsonb_build_object(
          'id',           r.id,
          'nombre',       r.name,
          'categoria',    r.category,
          'precio_venta', r.sale_price
        ) ORDER BY r.category, r.name)
        FROM public.recipes r
      ), '[]'::jsonb);
    END IF;

    -- Si hay nombre, buscar por similitud flexible
    IF v_nombre <> '' THEN
      -- Buscar coincidencias (ILIKE + similarity)
      -- Usamos una CTE para obtener las mejores y luego procesar la mejor
      WITH found AS (
        SELECT 
          id, 
          name, 
          category,
          sale_price,
          elaboration,
          presentation,
          similarity(lower(name), v_nombre) as sim
        FROM public.recipes
        WHERE lower(name) ILIKE '%' || v_nombre || '%' 
           OR similarity(lower(name), v_nombre) > 0.1
        ORDER BY sim DESC, name ASC
        LIMIT 5
      )
      SELECT * INTO v_best_match FROM found LIMIT 1;

      -- Obtener sugerencias (las otras 4)
      SELECT jsonb_agg(name) INTO v_matches 
      FROM (
        SELECT name, similarity(lower(name), v_nombre) as sim
        FROM public.recipes 
        WHERE (lower(name) ILIKE '%' || v_nombre || '%' OR similarity(lower(name), v_nombre) > 0.1)
          AND name <> v_best_match.name
        ORDER BY sim DESC, name ASC
        LIMIT 4
      ) s;

      SELECT count(*) INTO v_count_all FROM public.recipes;

      IF v_best_match.id IS NOT NULL THEN
        RETURN jsonb_build_object(
          'receta_encontrada', v_best_match.name,
          'debug', jsonb_build_object(
            'id_encontrado', v_best_match.id,
            'nombre_encontrado', v_best_match.name,
            'similitud', v_best_match.sim,
            'num_ingredientes', (SELECT count(*) FROM public.recipe_ingredients WHERE recipe_id = v_best_match.id),
            'total_recetas_en_tabla', v_count_all,
            'sugerencias', COALESCE(v_matches, '[]'::jsonb)
          ),
          'ingredientes', COALESCE((
            SELECT jsonb_agg(jsonb_build_object(
              'ingrediente',      i.name,
              'cantidad',         ri.quantity_gross,
              'unidad',           ri.unit,
              'precio_unitario',  i.current_price
            ))
            FROM public.recipe_ingredients ri
            JOIN public.ingredients i ON i.id = ri.ingredient_id
            WHERE ri.recipe_id = v_best_match.id
          ), '[]'::jsonb),
          'precio_venta', v_best_match.sale_price,
          'elaboracion',  v_best_match.elaboration,
          'presentacion', v_best_match.presentation
        );
      ELSE
        RETURN jsonb_build_object(
          'error', 'receta_no_encontrada',
          'nombre_buscado', v_nombre,
          'debug', jsonb_build_object(
            'total_recetas_en_tabla', v_count_all,
            'sugerencias', COALESCE(v_matches, '[]'::jsonb)
          )
        );
      END IF;
    ELSE
       -- Búsqueda vacía sin acción listar
       RETURN jsonb_build_object('error', 'nombre_vacio', 'mensaje', 'Indica el nombre de la receta');
    END IF;
  END IF;

  RETURN jsonb_build_object('error', 'accion_no_soportada', 'acciones_validas', '["buscar","listar"]');
END;

DECLARE
    b_key TEXT;
    b_val INT;
BEGIN
    IF TG_OP IN ('UPDATE', 'DELETE') THEN
        IF OLD.type IN ('IN', 'OUT', 'CLOSE_ENTRY') THEN
            IF OLD.breakdown IS NOT NULL AND OLD.breakdown != '{}'::jsonb THEN
                FOR b_key, b_val IN SELECT * FROM jsonb_each_text(OLD.breakdown) LOOP
                    IF OLD.type IN ('IN', 'CLOSE_ENTRY') THEN
                        UPDATE cash_box_inventory SET quantity = quantity - b_val WHERE box_id = OLD.box_id AND denomination = b_key::numeric;
                    ELSE
                        UPDATE cash_box_inventory SET quantity = quantity + b_val WHERE box_id = OLD.box_id AND denomination = b_key::numeric;
                    END IF;
                END LOOP;
            END IF;
            UPDATE cash_boxes SET current_balance = current_balance + (CASE WHEN OLD.type = 'OUT' THEN OLD.amount ELSE -OLD.amount END) WHERE id = OLD.box_id;
        ELSIF OLD.type = 'SWAP' THEN
            IF OLD.breakdown IS NOT NULL AND OLD.breakdown ? 'out' THEN
                FOR b_key, b_val IN SELECT * FROM jsonb_each_text(OLD.breakdown->'out') LOOP
                    INSERT INTO cash_box_inventory (box_id, denomination, quantity) VALUES (OLD.box_id, b_key::numeric, b_val::int) ON CONFLICT (box_id, denomination) DO UPDATE SET quantity = cash_box_inventory.quantity + b_val::int;
                END LOOP;
            END IF;
            IF OLD.breakdown IS NOT NULL AND OLD.breakdown ? 'in' THEN
                FOR b_key, b_val IN SELECT * FROM jsonb_each_text(OLD.breakdown->'in') LOOP
                    UPDATE cash_box_inventory SET quantity = quantity - b_val::int WHERE box_id = OLD.box_id AND denomination = b_key::numeric;
                END LOOP;
            END IF;
        ELSIF OLD.type = 'EXCHANGE' THEN
            IF OLD.breakdown IS NOT NULL AND OLD.breakdown != '{}'::jsonb AND OLD.to_box_id IS NOT NULL THEN
                FOR b_key, b_val IN SELECT * FROM jsonb_each_text(OLD.breakdown) LOOP
                    UPDATE cash_box_inventory SET quantity = quantity + b_val::int WHERE box_id = OLD.box_id AND denomination = b_key::numeric;
                    UPDATE cash_box_inventory SET quantity = quantity - b_val::int WHERE box_id = OLD.to_box_id AND denomination = b_key::numeric;
                END LOOP;
            END IF;
        END IF;
    END IF;
    IF TG_OP IN ('INSERT', 'UPDATE') THEN
        IF NEW.type IN ('IN', 'OUT', 'CLOSE_ENTRY') THEN
            IF NEW.breakdown IS NOT NULL AND NEW.breakdown != '{}'::jsonb THEN
                FOR b_key, b_val IN SELECT * FROM jsonb_each_text(NEW.breakdown) LOOP
                    IF NEW.type IN ('IN', 'CLOSE_ENTRY') THEN
                        INSERT INTO cash_box_inventory (box_id, denomination, quantity) VALUES (NEW.box_id, b_key::numeric, b_val) ON CONFLICT (box_id, denomination) DO UPDATE SET quantity = cash_box_inventory.quantity + EXCLUDED.quantity;
                    ELSIF NEW.type = 'OUT' THEN
                        UPDATE cash_box_inventory SET quantity = quantity - b_val WHERE box_id = NEW.box_id AND denomination = b_key::numeric;
                    END IF;
                END LOOP;
            END IF;
            UPDATE cash_boxes SET current_balance = current_balance + (CASE WHEN NEW.type = 'OUT' THEN -NEW.amount ELSE NEW.amount END) WHERE id = NEW.box_id;
        ELSIF NEW.type = 'SWAP' THEN
            IF NEW.breakdown IS NOT NULL AND NEW.breakdown ? 'out' THEN
                FOR b_key, b_val IN SELECT * FROM jsonb_each_text(NEW.breakdown->'out') LOOP
                    UPDATE cash_box_inventory SET quantity = quantity - b_val::int WHERE box_id = NEW.box_id AND denomination = b_key::numeric;
                END LOOP;
            END IF;
            IF NEW.breakdown IS NOT NULL AND NEW.breakdown ? 'in' THEN
                FOR b_key, b_val IN SELECT * FROM jsonb_each_text(NEW.breakdown->'in') LOOP
                    INSERT INTO cash_box_inventory (box_id, denomination, quantity) VALUES (NEW.box_id, b_key::numeric, b_val::int) ON CONFLICT (box_id, denomination) DO UPDATE SET quantity = cash_box_inventory.quantity + b_val::int;
                END LOOP;
            END IF;
        ELSIF NEW.type = 'EXCHANGE' THEN
            IF NEW.breakdown IS NOT NULL AND NEW.breakdown != '{}'::jsonb AND NEW.to_box_id IS NOT NULL THEN
                FOR b_key, b_val IN SELECT * FROM jsonb_each_text(NEW.breakdown) LOOP
                    UPDATE cash_box_inventory SET quantity = quantity - b_val::int WHERE box_id = NEW.box_id AND denomination = b_key::numeric;
                    INSERT INTO cash_box_inventory (box_id, denomination, quantity) VALUES (NEW.to_box_id, b_key::numeric, b_val::int) ON CONFLICT (box_id, denomination) DO UPDATE SET quantity = cash_box_inventory.quantity + b_val::int;
                END LOOP;
            END IF;
        ELSIF NEW.type = 'ADJUSTMENT' THEN
            IF NEW.breakdown IS NOT NULL AND NEW.breakdown != '{}'::jsonb THEN
                DELETE FROM cash_box_inventory WHERE box_id = NEW.box_id;
                FOR b_key, b_val IN SELECT * FROM jsonb_each_text(NEW.breakdown) LOOP
                    IF b_val::int > 0 THEN
                        INSERT INTO cash_box_inventory (box_id, denomination, quantity) VALUES (NEW.box_id, b_key::numeric, b_val::int);
                    END IF;
                END LOOP;
            END IF;
            UPDATE cash_boxes SET current_balance = NEW.amount WHERE id = NEW.box_id;
        END IF;
    END IF;
    RETURN COALESCE(NEW, OLD);
END;

DECLARE
  v_supplier_id       bigint;
  v_factor            numeric;
  v_content_qty       numeric;
  v_content_unit      text;
  v_purchase_unit     text;
  v_base_unit         text;
  v_qty_in_purchase   numeric;
  v_qty_in_base       numeric;
  v_ref               text;
BEGIN
  -- Solo al mapear (transición a status = 'mapped')
  IF NEW.mapped_ingredient_id IS NULL THEN RETURN NEW; END IF;
  IF COALESCE(NEW.status, '') <> 'mapped' THEN RETURN NEW; END IF;
  -- No reinsertar si ya estaba mapeada
  IF OLD.mapped_ingredient_id IS NOT NULL AND COALESCE(OLD.status, '') = 'mapped' THEN
    RETURN NEW;
  END IF;

  -- Requiere proveedor en la cabecera del albarán
  SELECT supplier_id INTO v_supplier_id
  FROM public.purchase_invoices
  WHERE id = NEW.invoice_id;
  IF v_supplier_id IS NULL THEN RETURN NEW; END IF;

  -- Obtener factor y tríada dimensional del mapeo
  SELECT conversion_factor, line_content_qty, line_content_unit
  INTO   v_factor, v_content_qty, v_content_unit
  FROM   public.supplier_item_mappings
  WHERE  supplier_id         = v_supplier_id
    AND  supplier_item_name  = NEW.original_name
    AND  ingredient_id       = NEW.mapped_ingredient_id
  LIMIT 1;

  IF v_factor IS NULL OR v_factor = 0 THEN RETURN NEW; END IF;

  -- Unidades del ingrediente (ambas ya sincronizadas tras la migración)
  SELECT purchase_unit, base_unit
  INTO   v_purchase_unit, v_base_unit
  FROM   public.ingredients
  WHERE  id = NEW.mapped_ingredient_id;

  -- ── Paso 1: cantidad en purchase_unit ──────────────────────────────────────
  IF v_content_qty IS NOT NULL AND v_content_unit IS NOT NULL THEN
    -- Modo tríada dimensional
    -- Ejemplo: 6 botellas × convert(750 ml → L) = 6 × 0.75 = 4.5 L
    v_qty_in_purchase :=
      COALESCE(NEW.quantity, 0)
      * public.convert_pricing_qty(v_content_qty, v_content_unit, v_purchase_unit);
  ELSE
    -- Modo factor escalar
    -- Ejemplo: 10 sacos × 25 (kg/saco) = 250 kg
    v_qty_in_purchase := COALESCE(NEW.quantity, 0) * v_factor;
  END IF;

  IF v_qty_in_purchase IS NULL OR v_qty_in_purchase <= 0 THEN RETURN NEW; END IF;

  -- ── Paso 2: convertir purchase_unit → base_unit ───────────────────────────
  -- Ejemplo: 4.5 L → 4500 ml | 250 kg → 250000 g | 10 ud → 10 ud
  v_qty_in_base := public.convert_pricing_qty(v_qty_in_purchase, v_purchase_unit, v_base_unit);

  IF v_qty_in_base IS NULL OR v_qty_in_base <= 0 THEN RETURN NEW; END IF;

  -- ── Idempotencia ──────────────────────────────────────────────────────────
  v_ref := 'ALB-LINE-' || NEW.id::text;
  IF EXISTS (
    SELECT 1 FROM public.stock_movements
    WHERE movement_type  = 'PURCHASE'
      AND ingredient_id  = NEW.mapped_ingredient_id
      AND reference_doc  = v_ref
    LIMIT 1
  ) THEN RETURN NEW; END IF;

  -- ── Insertar movimiento en base_unit ─────────────────────────────────────
  INSERT INTO public.stock_movements (
    movement_type, ingredient_id, quantity, unit,
    movement_date, reference_doc, original_description, processed_by
  ) VALUES (
    'PURCHASE',
    NEW.mapped_ingredient_id,
    v_qty_in_base,
    v_base_unit,
    now(),
    v_ref,
    'Recepción (auto): ' || COALESCE(NEW.original_name, ''),
    'Auto-Albaranes'
  );

  RETURN NEW;
END;

DECLARE
  v_event public.events%ROWTYPE;
  v_token uuid;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'no_autenticado'; END IF;
  IF NOT public.can_manage_encargos() THEN RAISE EXCEPTION 'sin_permiso'; END IF;

  SELECT * INTO v_event FROM public.events e WHERE e.id = p_event_id LIMIT 1;
  IF v_event.id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'not_found');
  END IF;

  IF v_event.client_order_submitted_at IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'not_submitted');
  END IF;

  v_token := coalesce(v_event.client_edit_token, gen_random_uuid());

  UPDATE public.events
  SET client_edit_enabled = true,
      client_edit_token = v_token,
      client_order_submitted_at = NULL,
      updated_at = now()
  WHERE id = v_event.id;

  RETURN jsonb_build_object('ok', true, 'event_id', v_event.id, 'client_edit_token', v_token);
END;

