DECLARE
  v_converted_qty numeric;
BEGIN
  IF p_mapping_content_qty IS NOT NULL AND p_mapping_content_unit IS NOT NULL THEN
    v_converted_qty := public.convert_pricing_qty(p_mapping_content_qty, p_mapping_content_unit, p_ingredient_purchase_unit);

    IF v_converted_qty IS NULL OR v_converted_qty = 0 THEN
      RETURN NULL; 
    END IF;

    RETURN p_unit_price / v_converted_qty;
  END IF;

  RETURN p_unit_price / COALESCE(NULLIF(p_fallback_factor, 0), 1);
END;

DECLARE
  v_order_id uuid;
  v_event_id uuid;
  v_enabled_ids text[];
  v_total numeric := 0;
  v_item jsonb;
  v_pid text;
  v_qty integer;
  v_line_notes text;
  v_half_notes text;
  v_is_half boolean;
  v_name text;
  v_price numeric;
  v_category text;
  v_base_name text;
  v_base_price numeric;
  v_items_out jsonb := '[]'::jsonb;
  v_any boolean := false;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'no_autenticado'; END IF;
  IF NOT public.can_manage_encargos() THEN RAISE EXCEPTION 'sin_permiso'; END IF;

  SELECT o.id, o.event_id INTO v_order_id, v_event_id
  FROM public.event_orders o WHERE o.id = p_order_id LIMIT 1;

  IF v_order_id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'not_found');
  END IF;

  SELECT e.enabled_product_ids INTO v_enabled_ids
  FROM public.events e WHERE e.id = v_event_id LIMIT 1;

  IF jsonb_typeof(p_items) IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'items_invalidos'; END IF;

  FOR v_item IN SELECT * FROM jsonb_array_elements(p_items) LOOP
    v_pid := trim(coalesce(v_item->>'product_id', ''));
    v_qty := NULLIF(trim(coalesce(v_item->>'quantity', '')), '')::int;
    v_line_notes := NULLIF(trim(coalesce(v_item->>'notes', '')), '');
    v_is_half := coalesce((v_item->>'is_half')::boolean, false)
      OR lower(coalesce(v_line_notes, '')) IN ('1/2', '½', 'medio', 'mitad', 'half');

    IF v_pid = '' THEN RAISE EXCEPTION 'product_id_requerido'; END IF;
    IF v_qty IS NULL OR v_qty <= 0 THEN RAISE EXCEPTION 'quantity_invalida'; END IF;

    IF v_enabled_ids IS NOT NULL AND array_length(v_enabled_ids, 1) > 0 AND NOT (v_pid = ANY(v_enabled_ids)) THEN
      RAISE EXCEPTION 'producto_no_permitido: %', v_pid;
    END IF;

    v_name := NULL; v_price := NULL; v_category := NULL;

    SELECT ep.name, ep.price, ep.category INTO v_name, v_price, v_category
    FROM public.event_products ep
    WHERE ep.product_id = v_pid AND ep.is_active = true
    LIMIT 1;

    IF v_name IS NULL OR v_price IS NULL THEN
      SELECT
        trim(coalesce(v.carta_nombre, '')),
        v.precio::numeric,
        nullif(
          trim(
            both ' · '
            from concat_ws(
              ' · ',
              nullif(trim(coalesce(v.category_parent_name, '')), ''),
              nullif(trim(coalesce(v.category_child_name, '')), '')
            )
          ),
          ''
        )
      INTO v_name, v_price, v_category
      FROM public.v_staff_encargo_menu_items v
      WHERE v.articulo_id::text = v_pid
      LIMIT 1;
    END IF;

    IF v_name IS NULL OR v_name = '' OR v_price IS NULL THEN
      RAISE EXCEPTION 'producto_no_disponible: %', v_pid;
    END IF;

    v_base_name := v_name;
    v_base_price := v_price;

    INSERT INTO public.event_products (product_id, name, price, category, is_active)
    VALUES (v_pid, v_base_name, v_base_price, v_category, true)
    ON CONFLICT (product_id) DO UPDATE SET
      name = EXCLUDED.name,
      price = EXCLUDED.price,
      category = COALESCE(EXCLUDED.category, public.event_products.category),
      is_active = true,
      updated_at = now();

    SELECT a.out_name, a.out_price, a.out_notes
    INTO v_name, v_price, v_half_notes
    FROM public.fn_event_order_apply_racion(v_pid, v_base_name, v_base_price, v_is_half) a;
    v_line_notes := coalesce(v_half_notes, v_line_notes);

    v_any := true;
    v_total := v_total + (v_price * v_qty);
    v_items_out := v_items_out || jsonb_build_array(
      jsonb_build_object(
        'product_id', v_pid,
        'name', v_name,
        'quantity', v_qty,
        'unit_price', v_price,
        'notes', v_line_notes,
        'is_half', v_is_half
      )
    );
  END LOOP;

  IF v_any IS DISTINCT FROM true THEN RAISE EXCEPTION 'items_vacios'; END IF;

  UPDATE public.event_orders
  SET items = v_items_out, total_amount = v_total
  WHERE id = v_order_id;

  UPDATE public.events
  SET filled_by = COALESCE(filled_by, 'staff'), updated_at = now()
  WHERE id = v_event_id;

  RETURN jsonb_build_object(
    'ok', true,
    'id', v_order_id,
    'event_id', v_event_id,
    'items', v_items_out,
    'total_amount', v_total
  );
END;

DECLARE
  v_len integer;
BEGIN
  IF NOT public.is_hector_consumption_order_editor() THEN
    RAISE EXCEPTION 'No autorizado: solo Hector puede modificar el orden';
  END IF;

  v_len := COALESCE(array_length(p_ordered_recipe_ids, 1), 0);
  IF v_len = 0 THEN
    RAISE EXCEPTION 'La lista de productos no puede estar vacía';
  END IF;

  INSERT INTO public.staff_consumption_recipe_display_order (recipe_id, sort_order, updated_at)
  SELECT
    rid,
    (ord - 1) * 10,
    now()
  FROM unnest(p_ordered_recipe_ids) WITH ORDINALITY AS t(rid, ord)
  ON CONFLICT (recipe_id) DO UPDATE SET
    sort_order = EXCLUDED.sort_order,
    updated_at = EXCLUDED.updated_at;

  DELETE FROM public.staff_consumption_recipe_display_order o
  WHERE o.recipe_id <> ALL (p_ordered_recipe_ids);
END;

DECLARE
  v     numeric;
  piece numeric;
BEGIN
  IF p_qty IS NULL THEN RETURN NULL; END IF;

  -- Intento directo: misma familia dimensional (g↔kg, ml↔l↔cl, ud↔ud)
  v := public.convert_pricing_qty(p_qty, p_recipe_unit, p_base_unit);
  IF v IS NOT NULL THEN RETURN v; END IF;

  -- Puente per_pack A: receta en ud → base_unit masa o volumen
  -- Ejemplo: 2 ud de botella de 330 ml → 660 ml
  IF public.normalize_pricing_unit(p_recipe_unit) = 'ud'
     AND p_base_unit IN ('ml', 'g')
     AND lower(trim(coalesce(p_mode, ''))) = 'per_pack'
     AND p_pack_qty IS NOT NULL AND p_pack_qty > 0
     AND p_pack_unit IS NOT NULL AND trim(p_pack_unit) <> '' THEN
    piece := public.convert_pricing_qty(p_pack_qty, p_pack_unit, p_base_unit);
    IF piece IS NOT NULL AND piece > 0 THEN
      RETURN p_qty * piece;
    END IF;
  END IF;

  -- Dimensiones incompatibles sin puente: no hay conversión posible
  RETURN NULL;
END;

DECLARE
  v_line_id uuid;
  v_invoice_id uuid;
  v_suffix text;
BEGIN
  IF NEW.movement_type IS DISTINCT FROM 'PURCHASE' THEN
    RETURN NEW;
  END IF;

  v_suffix := COALESCE(NEW.reference_doc, '');
  IF v_suffix NOT LIKE 'ALB-LINE-%' THEN
    RETURN NEW;
  END IF;

  BEGIN
    v_line_id := substring(v_suffix FROM 10)::uuid;
  EXCEPTION
    WHEN OTHERS THEN
      RETURN NEW;
  END;

  SELECT pil.invoice_id
  INTO v_invoice_id
  FROM public.purchase_invoice_lines pil
  WHERE pil.id = v_line_id;

  IF v_invoice_id IS NOT NULL THEN
    PERFORM public.sync_purchase_invoice_status(v_invoice_id);
  END IF;

  RETURN NEW;
END;

DECLARE
  v_status text;
  v_line_count int;
  v_unresolved int;
  v_stock_missing int;
  v_fully_processed boolean;
BEGIN
  IF p_invoice_id IS NULL THEN
    RETURN;
  END IF;

  SELECT status INTO v_status
  FROM public.purchase_invoices
  WHERE id = p_invoice_id;

  IF NOT FOUND THEN
    RETURN;
  END IF;

  IF v_status IN ('completed', 'processing', 'ocr_failed') THEN
    RETURN;
  END IF;

  SELECT COUNT(*)::int INTO v_line_count
  FROM public.purchase_invoice_lines
  WHERE invoice_id = p_invoice_id;

  IF v_line_count = 0 THEN
    IF v_status = 'mapped' THEN
      UPDATE public.purchase_invoices
      SET status = 'pending_mapping'
      WHERE id = p_invoice_id;
    END IF;
    RETURN;
  END IF;

  SELECT COUNT(*)::int INTO v_unresolved
  FROM public.purchase_invoice_lines pil
  WHERE pil.invoice_id = p_invoice_id
    AND NOT (
      pil.status IN ('excluded', 'expense_only')
      OR (
        pil.mapped_ingredient_id IS NOT NULL
        AND COALESCE(pil.status, '') = 'mapped'
      )
    );

  IF v_unresolved > 0 THEN
    IF v_status = 'mapped' THEN
      UPDATE public.purchase_invoices
      SET status = 'pending_mapping'
      WHERE id = p_invoice_id;
    END IF;
    RETURN;
  END IF;

  SELECT COUNT(*)::int INTO v_stock_missing
  FROM public.purchase_invoice_lines pil
  WHERE pil.invoice_id = p_invoice_id
    AND COALESCE(pil.status, '') = 'mapped'
    AND pil.mapped_ingredient_id IS NOT NULL
    AND NOT EXISTS (
      SELECT 1
      FROM public.stock_movements sm
      WHERE sm.movement_type = 'PURCHASE'
        AND sm.ingredient_id = pil.mapped_ingredient_id
        AND sm.reference_doc = 'ALB-LINE-' || pil.id::text
    );

  v_fully_processed := v_stock_missing = 0;

  IF v_fully_processed THEN
    IF v_status IS DISTINCT FROM 'mapped' THEN
      UPDATE public.purchase_invoices
      SET status = 'mapped'
      WHERE id = p_invoice_id;
    END IF;
  ELSIF v_status = 'mapped' THEN
    UPDATE public.purchase_invoices
    SET status = 'pending_mapping'
    WHERE id = p_invoice_id;
  END IF;
END;

