DECLARE
  v_medio numeric;
  v_name text;
BEGIN
  IF p_is_half IS DISTINCT FROM true THEN
    RETURN QUERY SELECT p_name, p_price, NULL::text;
    RETURN;
  END IF;

  SELECT o.override_precio_medio
  INTO v_medio
  FROM public.digital_menu_overrides o
  WHERE o.articulo_id::text = p_product_id
    AND coalesce(o.carta_dual_racion_enabled, false) = true
  LIMIT 1;

  IF v_medio IS NULL OR v_medio <= 0 THEN
    SELECT v.override_precio_medio::numeric
    INTO v_medio
    FROM public.v_public_menu_items v
    WHERE v.articulo_id::text = p_product_id
      AND coalesce(v.carta_dual_racion_enabled, false) = true
    LIMIT 1;
  END IF;

  IF v_medio IS NULL OR v_medio <= 0 THEN
    RAISE EXCEPTION 'producto_medio_no_disponible: %', p_product_id;
  END IF;

  v_name := coalesce(nullif(trim(p_name), ''), 'Producto');
  v_name := regexp_replace(v_name, '^\s*(1/2|½)\s*[·.\-]?\s*', '', 'i');
  v_name := trim(regexp_replace(v_name, '\s+', ' ', 'g'));
  v_name := '1/2 ' || v_name;

  RETURN QUERY SELECT v_name, v_medio, NULL::text;
END;

declare
  v_url text;
  v_bearer text;
  v_request_id bigint;
begin
  if p_slot is distinct from 'winter' and p_slot is distinct from 'summer' then
    raise exception 'fn_cron_request_persist_overtime_cost: slot inválido %', p_slot;
  end if;

  select value into v_url
  from public.app_settings
  where key = 'recalc_balances_cron_url';

  select value into v_bearer
  from public.app_settings
  where key = 'cron_recalc_bearer';

  if v_url is null or length(trim(v_url)) = 0 then
    raise exception
      'Falta app_settings.recalc_balances_cron_url';
  end if;

  if v_bearer is null
     or length(trim(v_bearer)) = 0
     or v_bearer = 'REPLACE_WITH_CRON_SECRET' then
    raise exception
      'Falta app_settings.cron_recalc_bearer (= CRON_SECRET de Vercel)';
  end if;

  v_url := split_part(v_url, '?', 1);

  -- mode=full → Writer writeWeeklyProjection (sin RPC SQL de horas)
  select net.http_get(
    url := v_url,
    params := jsonb_build_object(
      'slot', p_slot
    ),
    headers := jsonb_build_object(
      'Authorization', 'Bearer ' || v_bearer,
      'Content-Type', 'application/json'
    ),
    timeout_milliseconds := 290000
  )
  into v_request_id;

  return v_request_id;
end;

begin
  -- Fase 1c: no-op (antes invocaba el motor SQL de snapshots).
  -- Proyección columnas C: únicamente writeWeeklyProjection (TS).
  return coalesce(new, old);
end;

declare
  v_eff date;
  v_regime text;
  v_weekly numeric;
  v_bag boolean;
  v_rate numeric;
  v_open record;
  v_day_before date;
  v_same boolean;
begin
  v_eff := (timezone('Europe/Madrid', now()))::date;

  if new.role = 'manager' then
    v_regime := 'manager';
  elsif coalesce(new.is_fixed_salary, false) then
    v_regime := 'fixed';
  else
    v_regime := 'staff';
  end if;

  if v_regime in ('manager', 'fixed') then
    v_weekly := 0;
  else
    v_weekly := coalesce(new.contracted_hours_weekly, 40);
  end if;

  v_bag := coalesce(new.prefer_stock_hours, false);
  v_rate := new.overtime_cost_per_hour;

  if tg_op = 'INSERT' then
    if not exists (
      select 1 from public.hours_contract_terms t where t.user_id = new.id
    ) then
      insert into public.hours_contract_terms (
        user_id, effective_from, effective_to, weekly_hours, bag_mode, regime, overtime_rate_per_hour
      ) values (
        new.id,
        coalesce(new.joining_date, v_eff),
        null,
        v_weekly,
        v_bag,
        v_regime,
        v_rate
      );
    end if;
    return new;
  end if;

  if tg_op = 'UPDATE' then
    if
      new.contracted_hours_weekly is not distinct from old.contracted_hours_weekly
      and new.prefer_stock_hours is not distinct from old.prefer_stock_hours
      and new.is_fixed_salary is not distinct from old.is_fixed_salary
      and new.overtime_cost_per_hour is not distinct from old.overtime_cost_per_hour
      and new.role is not distinct from old.role
    then
      return new;
    end if;

    select *
    into v_open
    from public.hours_contract_terms t
    where t.user_id = new.id and t.effective_to is null
    order by t.effective_from desc
    limit 1;

    if not found then
      insert into public.hours_contract_terms (
        user_id, effective_from, effective_to, weekly_hours, bag_mode, regime, overtime_rate_per_hour
      ) values (
        new.id, v_eff, null, v_weekly, v_bag, v_regime, v_rate
      );
      return new;
    end if;

    v_same :=
      v_open.weekly_hours = v_weekly
      and v_open.bag_mode = v_bag
      and v_open.regime = v_regime
      and v_open.overtime_rate_per_hour is not distinct from v_rate;

    if v_same then
      return new;
    end if;

    if v_open.effective_from = v_eff then
      update public.hours_contract_terms
      set
        weekly_hours = v_weekly,
        bag_mode = v_bag,
        regime = v_regime,
        overtime_rate_per_hour = v_rate
      where id = v_open.id;
      return new;
    end if;

    if v_eff <= v_open.effective_from then
      raise exception
        'fn_hours_contract_terms_sync_from_profile: fecha efectiva % no posterior al tramo abierto %',
        v_eff, v_open.effective_from;
    end if;

    v_day_before := v_eff - 1;

    update public.hours_contract_terms
    set effective_to = v_day_before
    where id = v_open.id;

    insert into public.hours_contract_terms (
      user_id, effective_from, effective_to, weekly_hours, bag_mode, regime, overtime_rate_per_hour
    ) values (
      new.id, v_eff, null, v_weekly, v_bag, v_regime, v_rate
    );
  end if;

  return new;
end;

DECLARE
  v_id uuid;
  v_new_status text;
BEGIN
  v_id := NULLIF(trim(both from (p_datos->>'id')), '')::uuid;

  IF v_id IS NULL THEN
    RAISE EXCEPTION 'reservation id requerido';
  END IF;

  IF p_accion = 'delete' THEN
    BEGIN
      DELETE FROM public.reservations WHERE id = v_id;

      IF NOT FOUND THEN
        RETURN jsonb_build_object('error', 'not_found', 'id', v_id);
      END IF;

      RETURN jsonb_build_object('ok', true, 'id', v_id, 'deleted', true);
    EXCEPTION
      WHEN OTHERS THEN
        UPDATE public.reservations
        SET status = 'cancelled'
        WHERE id = v_id;

        IF NOT FOUND THEN
          RETURN jsonb_build_object('error', 'not_found', 'id', v_id);
        END IF;

        RETURN jsonb_build_object(
          'ok', true,
          'id', v_id,
          'status', 'cancelled',
          'soft_deleted', true
        );
    END;
  END IF;

  v_new_status := CASE p_accion
    WHEN 'confirm' THEN 'confirmed'
    WHEN 'reject' THEN 'rejected'
    WHEN 'cancel' THEN 'cancelled'
    ELSE NULL
  END;

  IF v_new_status IS NULL THEN
    RAISE EXCEPTION 'accion_invalida: %', p_accion;
  END IF;

  UPDATE public.reservations
  SET status = v_new_status
  WHERE id = v_id;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('error', 'not_found', 'id', v_id);
  END IF;

  RETURN jsonb_build_object('ok', true, 'id', v_id, 'status', v_new_status);
END;

DECLARE
  v_event_id uuid;
  v_event_date date;
  v_event_time time;
  v_event_active boolean;
  v_enabled_ids text[];
  v_event_ts timestamptz;

  v_responsible text;
  v_total numeric := 0;
  v_item jsonb;
  v_pid text;
  v_qty integer;
  v_name text;
  v_price numeric;
  v_category text;
  v_items_out jsonb := '[]'::jsonb;
  v_any boolean := false;
  v_order_id uuid;

  y int;
  mo int;
  d int;
  hh int;
  mi int;
BEGIN
  v_responsible := trim(coalesce(p_responsible_name, ''));
  IF v_responsible = '' THEN
    RAISE EXCEPTION 'responsable_requerido';
  END IF;

  IF p_slug IS NULL OR trim(p_slug) = '' THEN
    RAISE EXCEPTION 'slug_requerido';
  END IF;

  SELECT e.id, e.event_date, e.event_time, e.is_active, e.enabled_product_ids
  INTO v_event_id, v_event_date, v_event_time, v_event_active, v_enabled_ids
  FROM public.events e
  WHERE e.slug = trim(p_slug)
  LIMIT 1;

  IF v_event_id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'not_found');
  END IF;

  IF v_event_active IS DISTINCT FROM true THEN
    RETURN jsonb_build_object('ok', false, 'error', 'event_inactive');
  END IF;

  y := EXTRACT(YEAR FROM v_event_date)::int;
  mo := EXTRACT(MONTH FROM v_event_date)::int;
  d := EXTRACT(DAY FROM v_event_date)::int;
  hh := EXTRACT(HOUR FROM v_event_time)::int;
  mi := EXTRACT(MINUTE FROM v_event_time)::int;
  v_event_ts := make_timestamptz(y, mo, d, hh, mi, 0, 'Europe/Madrid');

  IF v_event_ts < now() THEN
    RETURN jsonb_build_object('ok', false, 'error', 'event_past');
  END IF;

  IF jsonb_typeof(p_items) IS DISTINCT FROM 'array' THEN
    RAISE EXCEPTION 'items_invalidos';
  END IF;

  FOR v_item IN SELECT * FROM jsonb_array_elements(p_items)
  LOOP
    v_pid := trim(coalesce(v_item->>'product_id', ''));
    v_qty := NULLIF(trim(coalesce(v_item->>'quantity', '')), '')::int;

    IF v_pid = '' THEN
      RAISE EXCEPTION 'product_id_requerido';
    END IF;
    IF v_qty IS NULL OR v_qty <= 0 THEN
      RAISE EXCEPTION 'quantity_invalida';
    END IF;

    IF v_enabled_ids IS NOT NULL AND NOT (v_pid = ANY(v_enabled_ids)) THEN
      RAISE EXCEPTION 'producto_no_permitido: %', v_pid;
    END IF;

    v_name := NULL;
    v_price := NULL;
    v_category := NULL;

    SELECT ep.name, ep.price, ep.category
    INTO v_name, v_price, v_category
    FROM public.event_products ep
    WHERE ep.product_id = v_pid
      AND ep.is_active = true
    LIMIT 1;

    IF v_name IS NULL OR v_price IS NULL THEN
      SELECT
        trim(coalesce(v.carta_nombre, '')),
        v.precio::numeric,
        nullif(
          trim(
            both ' · '
            from concat_ws(
              ' · ',
              nullif(trim(coalesce(v.category_parent_name, '')), ''),
              nullif(trim(coalesce(v.category_child_name, '')), '')
            )
          ),
          ''
        )
      INTO v_name, v_price, v_category
      FROM public.v_public_menu_items v
      WHERE v.articulo_id::text = v_pid
      LIMIT 1;
    END IF;

    IF v_name IS NULL OR v_name = '' OR v_price IS NULL THEN
      RAISE EXCEPTION 'producto_no_disponible: %', v_pid;
    END IF;

  INSERT INTO public.event_products (product_id, name, price, category, is_active)
  VALUES (v_pid, v_name, v_price, v_category, true)
  ON CONFLICT (product_id) DO UPDATE SET
    name = EXCLUDED.name,
    price = EXCLUDED.price,
    category = COALESCE(EXCLUDED.category, public.event_products.category),
    is_active = true,
    updated_at = now();

    v_any := true;
    v_total := v_total + (v_price * v_qty);
    v_items_out := v_items_out || jsonb_build_array(
      jsonb_build_object(
        'product_id', v_pid,
        'name', v_name,
        'quantity', v_qty,
        'unit_price', v_price
      )
    );
  END LOOP;

  IF v_any IS DISTINCT FROM true THEN
    RAISE EXCEPTION 'items_vacios';
  END IF;

  INSERT INTO public.event_orders(event_id, responsible_name, items, total_amount, notes)
  VALUES (v_event_id, v_responsible, v_items_out, v_total, NULLIF(trim(coalesce(p_notes,'')), ''))
  RETURNING id INTO v_order_id;

  RETURN jsonb_build_object(
    'ok', true,
    'id', v_order_id,
    'event_id', v_event_id,
    'responsible_name', v_responsible,
    'items', v_items_out,
    'total_amount', v_total,
    'status', 'pending'
  );
END;

DECLARE
  v_mapped int := 0;
  v_skipped int := 0;
  rec record;
  v_ingredient_id uuid;
  v_name text;
  v_sim numeric;
BEGIN
  FOR rec IN
    SELECT pil.id, pil.original_name, pi.supplier_id
    FROM public.purchase_invoice_lines pil
    INNER JOIN public.purchase_invoices pi ON pi.id = pil.invoice_id
    WHERE pil.mapped_ingredient_id IS NULL
      AND COALESCE(pil.status, 'pending') NOT IN ('excluded', 'expense_only')
      AND pi.supplier_id IS NOT NULL
      AND trim(COALESCE(pil.original_name, '')) <> ''
      AND (p_invoice_id IS NULL OR pil.invoice_id = p_invoice_id)
  LOOP
    v_ingredient_id := NULL;
    v_name := lower(trim(rec.original_name));

    -- Match exacto (case-insensitive)
    SELECT m.ingredient_id
    INTO v_ingredient_id
    FROM public.supplier_item_mappings m
    WHERE m.supplier_id = rec.supplier_id
      AND lower(trim(m.supplier_item_name)) = v_name
      AND m.ingredient_id IS NOT NULL
      AND COALESCE(m.conversion_factor, 0) > 0
    LIMIT 1;

    -- Match fuzzy (pg_trgm)
    IF v_ingredient_id IS NULL AND v_name <> '' THEN
      SELECT m.ingredient_id, similarity(lower(trim(m.supplier_item_name)), v_name)
      INTO v_ingredient_id, v_sim
      FROM public.supplier_item_mappings m
      WHERE m.supplier_id = rec.supplier_id
        AND m.ingredient_id IS NOT NULL
        AND COALESCE(m.conversion_factor, 0) > 0
        AND similarity(lower(trim(m.supplier_item_name)), v_name) >= p_similarity_threshold
      ORDER BY similarity(lower(trim(m.supplier_item_name)), v_name) DESC
      LIMIT 1;
    END IF;

    IF v_ingredient_id IS NOT NULL THEN
      UPDATE public.purchase_invoice_lines
      SET mapped_ingredient_id = v_ingredient_id,
          status = 'mapped'
      WHERE id = rec.id;
      v_mapped := v_mapped + 1;
    ELSE
      v_skipped := v_skipped + 1;
    END IF;
  END LOOP;

  RETURN jsonb_build_object('mapped', v_mapped, 'skipped', v_skipped);
END;

declare
  v_offset integer;
begin
  -- DST Madrid: CET=1 → winter (03:00 UTC), CEST=2 → summer (02:00 UTC).
  -- Misma guardia que cron_weekly_recalculate_balances_if_madrid_*.
  v_offset := public.madrid_utc_offset_hours(now());

  begin
    if v_offset = 2 then
      perform public.fn_cron_request_persist_overtime_cost('summer');
    else
      -- CET (1) u offset inesperado: winter (el endpoint puede skipped si DST no cuadra)
      perform public.fn_cron_request_persist_overtime_cost('winter');
    end if;
  exception when others then
    raise warning
      'Cron close-previous-week Fase 1d: Writer HTTP falló: %',
      SQLERRM;
  end;
end;

declare
    i int;
    v_day_hours numeric;
    v_date date;
    v_result jsonb := '[]'::jsonb;
    v_clock_in text;
    v_clock_out text;
    v_has_log boolean;
begin
    perform p_contracted_hours;

    for i in 0..6 loop
        v_date := p_start_date + i;

        select
            coalesce(sum(public.fn_calculate_rounded_hours(total_hours)), 0),
            to_char(min(clock_in at time zone 'Europe/Madrid'), 'HH24:MI'),
            to_char(max(clock_out at time zone 'Europe/Madrid'), 'HH24:MI'),
            count(id) > 0
        into v_day_hours, v_clock_in, v_clock_out, v_has_log
        from public.time_logs
        where user_id = p_user_id
          and date(clock_in at time zone 'Europe/Madrid') = v_date;

        v_result := v_result || jsonb_build_object(
            'date', v_date,
            'hasLog', v_has_log,
            'clockIn', coalesce(v_clock_in, ''),
            'clockOut', coalesce(v_clock_out, ''),
            'totalHours', v_day_hours,
            'extraHours', 0
        );
    end loop;

    return v_result;
end;

DECLARE
  v_ts timestamptz;
BEGIN
  IF p_hora_cierre IS NOT NULL AND btrim(p_hora_cierre) <> '' THEN
    IF p_hora_cierre ~ 'T' OR p_hora_cierre ~ '^[0-9]{4}-' THEN
      BEGIN
        v_ts := p_hora_cierre::timestamptz;
        RETURN v_ts;
      EXCEPTION
        WHEN OTHERS THEN
          NULL;
      END;
    END IF;

    IF p_fecha IS NOT NULL THEN
      BEGIN
        RETURN (
          p_fecha::timestamp
          + (
            CASE
              WHEN p_hora_cierre ~ 'T' THEN (split_part(split_part(p_hora_cierre, 'T', 2), '.', 1))::time
              WHEN p_hora_cierre ~ ' ' THEN (split_part(p_hora_cierre, ' ', 2))::time
              ELSE (substring(p_hora_cierre from 1 for 8))::time
            END
          )
        ) AT TIME ZONE 'Europe/Madrid';
      EXCEPTION
        WHEN OTHERS THEN
          NULL;
      END;
    END IF;
  END IF;

  RETURN COALESCE(
    p_fecha_real,
    CASE
      WHEN p_fecha IS NOT NULL THEN (p_fecha::timestamp AT TIME ZONE 'Europe/Madrid')
      ELSE NULL
    END
  );
END;

