DECLARE
  cart_rec RECORD;
  ing_rec RECORD;
  v_failed uuid[] := '{}';
BEGIN
  IF jsonb_array_length(p_items) = 0 THEN
    RETURN;
  END IF;

  FOR cart_rec IN
    SELECT cart.recipe_id, cart.quantity, cart.is_half, r.name AS recipe_name
    FROM jsonb_to_recordset(p_items) AS cart(recipe_id uuid, quantity numeric, is_half boolean)
    JOIN public.recipes r ON r.id = cart.recipe_id
  LOOP
    IF cart_rec.recipe_id = ANY (v_failed) THEN
      CONTINUE;
    END IF;

    BEGIN
      FOR ing_rec IN
        SELECT
          ri.unit AS recipe_unit,
          ri.quantity_gross,
          ri.quantity_half,
          ri.umb_multiplier,
          COALESCE(ing.purchase_unit, 'ud') AS purchase_unit,
          ing.supplier_pricing_mode,
          ing.pack_unit_size_qty,
          ing.pack_unit_size_unit,
          ing.name AS ingredient_name
        FROM public.recipe_ingredients ri
        JOIN public.ingredients ing ON ri.ingredient_id = ing.id
        WHERE ri.recipe_id = cart_rec.recipe_id
      LOOP
        PERFORM public.staff_consumption_qty_to_purchase_unit(
          (CASE
            WHEN cart_rec.is_half AND COALESCE(ing_rec.quantity_half, 0) > 0 THEN ing_rec.quantity_half
            ELSE ing_rec.quantity_gross * (CASE WHEN cart_rec.is_half THEN 0.5 ELSE 1.0 END)
          END) * cart_rec.quantity * ing_rec.umb_multiplier,
          ing_rec.recipe_unit,
          ing_rec.purchase_unit,
          ing_rec.supplier_pricing_mode,
          ing_rec.pack_unit_size_qty,
          ing_rec.pack_unit_size_unit,
          cart_rec.recipe_name,
          ing_rec.ingredient_name
        );
      END LOOP;
    EXCEPTION
      WHEN OTHERS THEN
        recipe_id := cart_rec.recipe_id;
        recipe_name := cart_rec.recipe_name;
        error_message := SQLERRM;
        RETURN NEXT;
        v_failed := array_append(v_failed, cart_rec.recipe_id);
    END;
  END LOOP;
END;

DECLARE
  v_converted numeric;
  v_denom numeric;
BEGIN
  IF p_target_current IS NULL OR p_target_current < 0 THEN
    RETURN NULL;
  END IF;
  IF p_pack_units IS NULL OR p_pack_units <= 0 THEN
    RETURN NULL;
  END IF;
  IF p_pack_unit_size_qty IS NULL OR p_pack_unit_size_qty <= 0 OR p_pack_unit_size_unit IS NULL THEN
    RETURN NULL;
  END IF;

  v_converted := public.convert_pricing_qty(
    p_pack_unit_size_qty,
    p_pack_unit_size_unit,
    public.normalize_pricing_unit(p_purchase_unit)
  );
  IF v_converted IS NULL OR v_converted <= 0 THEN
    RETURN NULL;
  END IF;

  v_denom := p_pack_units * v_converted;
  IF v_denom <= 0 THEN
    RETURN NULL;
  END IF;

  RETURN p_target_current * v_denom;
END;

DECLARE
  v_ingredient_id uuid;
  v_conversion_factor numeric;
  v_mapping_content_qty numeric;
  v_mapping_content_unit text;
  v_ingredient_purchase_unit text;
  v_supplier_pricing_mode text;
  v_pack_price numeric;
  v_pack_units numeric;
  v_pack_unit_size_qty numeric;
  v_pack_unit_size_unit text;
  v_old_price numeric;
  v_new_price numeric;
  v_price_locked boolean;
  v_next_pack_price numeric;
BEGIN
  SELECT
    m.ingredient_id,
    m.conversion_factor,
    m.line_content_qty,
    m.line_content_unit,
    i.purchase_unit,
    i.current_price,
    COALESCE(i.price_locked, false),
    COALESCE(i.supplier_pricing_mode, 'per_purchase_unit'),
    i.pack_price,
    i.pack_units,
    i.pack_unit_size_qty,
    i.pack_unit_size_unit
  INTO
    v_ingredient_id,
    v_conversion_factor,
    v_mapping_content_qty,
    v_mapping_content_unit,
    v_ingredient_purchase_unit,
    v_old_price,
    v_price_locked,
    v_supplier_pricing_mode,
    v_pack_price,
    v_pack_units,
    v_pack_unit_size_qty,
    v_pack_unit_size_unit
  FROM public.supplier_item_mappings m
  JOIN public.ingredients i ON i.id = m.ingredient_id
  WHERE m.supplier_id = (SELECT supplier_id FROM public.purchase_invoices WHERE id = NEW.invoice_id)
    AND m.supplier_item_name = NEW.original_name;

  IF v_ingredient_id IS NOT NULL THEN
    v_new_price := public.invoice_line_price_to_purchase_unit(
      NEW.unit_price,
      v_mapping_content_qty,
      v_mapping_content_unit,
      v_ingredient_purchase_unit,
      v_conversion_factor
    );

    IF v_new_price IS NULL THEN
      RAISE EXCEPTION 'Descuadre dimensional crítico en albarán. No se puede convertir el artículo "%" (unidad proveedor: %) a la unidad base de receta (%)',
        NEW.original_name, v_mapping_content_unit, v_ingredient_purchase_unit;
    END IF;

    IF NOT COALESCE(v_price_locked, false)
       AND NOT public.ingredient_prices_are_equal(COALESCE(v_old_price, 0), v_new_price) THEN
      IF v_supplier_pricing_mode = 'per_pack' THEN
        v_next_pack_price := public.pack_price_for_target_current(
          v_new_price,
          v_pack_units,
          v_pack_unit_size_qty,
          v_pack_unit_size_unit,
          v_ingredient_purchase_unit
        );
        IF v_next_pack_price IS NOT NULL
           AND NOT public.ingredient_prices_are_equal(COALESCE(v_pack_price, 0), v_next_pack_price) THEN
          INSERT INTO public.ingredient_price_history (ingredient_id, old_price, new_price, changed_at)
          VALUES (v_ingredient_id, COALESCE(v_old_price, 0), v_new_price, NOW());

          UPDATE public.ingredients
          SET pack_price = v_next_pack_price,
              updated_at = NOW()
          WHERE id = v_ingredient_id;
        ELSIF v_next_pack_price IS NULL
              AND NOT public.ingredient_prices_are_equal(COALESCE(v_old_price, 0), v_new_price) THEN
          INSERT INTO public.ingredient_price_history (ingredient_id, old_price, new_price, changed_at)
          VALUES (v_ingredient_id, COALESCE(v_old_price, 0), v_new_price, NOW());

          UPDATE public.ingredients
          SET current_price = v_new_price,
              updated_at = NOW()
          WHERE id = v_ingredient_id;
        END IF;
      ELSE
        INSERT INTO public.ingredient_price_history (ingredient_id, old_price, new_price, changed_at)
        VALUES (v_ingredient_id, COALESCE(v_old_price, 0), v_new_price, NOW());

        UPDATE public.ingredients
        SET current_price = v_new_price,
            updated_at = NOW()
        WHERE id = v_ingredient_id;
      END IF;
    END IF;

    UPDATE public.purchase_invoice_lines
    SET mapped_ingredient_id = v_ingredient_id,
        status = 'mapped'
    WHERE id = NEW.id;

    UPDATE public.supplier_item_mappings
    SET last_known_price = NEW.unit_price
    WHERE supplier_id = (SELECT supplier_id FROM public.purchase_invoices WHERE id = NEW.invoice_id)
      AND supplier_item_name = NEW.original_name;
  END IF;

  RETURN NEW;
END;

DECLARE
  v_event_id uuid;
  v_edit boolean;
  v_submitted timestamptz;
  v_items jsonb;
BEGIN
  IF p_token IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'token_requerido');
  END IF;

  SELECT e.id, e.client_edit_enabled, e.client_order_submitted_at
  INTO v_event_id, v_edit, v_submitted
  FROM public.events e
  WHERE e.client_edit_token = p_token
  LIMIT 1;

  IF v_event_id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'not_found');
  END IF;

  -- Solo con enlace abierto (incl. reabierto: submitted_at NULL)
  IF v_edit IS DISTINCT FROM true OR v_submitted IS NOT NULL THEN
    RETURN jsonb_build_object('ok', true, 'items', '[]'::jsonb);
  END IF;

  SELECT o.items
  INTO v_items
  FROM public.event_orders o
  WHERE o.event_id = v_event_id
    AND o.status IN ('pending', 'confirmed')
  ORDER BY
    CASE WHEN o.status = 'confirmed' THEN 0 ELSE 1 END,
    CASE WHEN jsonb_array_length(coalesce(o.items, '[]'::jsonb)) > 0 THEN 0 ELSE 1 END,
    o.created_at ASC
  LIMIT 1;

  RETURN jsonb_build_object(
    'ok', true,
    'items', coalesce(v_items, '[]'::jsonb)
  );
END;

